/* Finot Académie — Intelligence artificielle (IA) au collège, année scolaire 2026-2027 : 23 chapitres reconstruits (ia6a…ia3f).
   Cadre : enseignement transversal, en lien avec le programme de technologie du cycle 4 (arrêté du 9 février 2024, BO n°9 du
   29 février 2024, qui mentionne explicitement l'intelligence artificielle) et avec le CRCN (cadre de référence des compétences
   numériques, article D. 121-1 du Code de l'éducation) ; en 4e, deux parcours Pix obligatoires sont consacrés à l'IA depuis 2025-2027
   (note de service du 23 janvier 2026, BO n°6 du 5 février 2026) — voir data/college/pix.js (chapitre pix4h) pour ce dispositif
   précis. Les chapitres « ia » ci-dessous forment un approfondissement progressif, distinct de Pix, centré sur la compréhension
   du fonctionnement des IA, leurs limites et un usage responsable, en cohérence avec le RGPD (2018) et le droit d'auteur.
   Références complémentaires selon les chapitres : Éduscol (ressources IA et numérique) ; CNIL ; Code de la propriété intellectuelle. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const TECH='Programme de technologie du cycle 4 — arrêté du 9 février 2024 (NOR MENE2402802A), BO n°9 du 29 février 2024 (mention explicite de l’intelligence artificielle)';
const CRCN='Cadre de référence des compétences numériques (CRCN), article D. 121-1 du Code de l’éducation';
const PIXIA='Note de service du 23 janvier 2026 (NOR MENE2527173N), BO n°6 du 5 février 2026 — parcours Pix obligatoires sur l’IA en 4e';
const RGPD='Règlement général sur la protection des données (RGPD, 2018) et CNIL';
const CPI='Code de la propriété intellectuelle (droit d’auteur)';
const EDU='Éduscol — ressources sur le numérique et l’intelligence artificielle (eduscol.education.gouv.fr)';

MQ.add('ia','6',[
{id:'ia6a',name:'Qu’est-ce qu’une intelligence artificielle ?',icon:'🤖',domain:'Comprendre l’IA',
 refs:[TECH,CRCN,EDU],
 tip:'Une IA ne « pense » pas comme un humain : elle suit des règles ou reconnaît des régularités dans des exemples pour produire un résultat.',
 c:C(`On entend parler d’<b>intelligence artificielle</b> (IA) pour une voiture qui se gare seule, un assistant qui répond à des questions, ou un jeu vidéo. Mais qu’est-ce qu’une IA, vraiment ?`,
  [T('Une définition simple',`<p>Une <b>intelligence artificielle</b> est un programme informatique conçu pour réaliser des <b>tâches</b> qui demandent, chez un humain, de l’intelligence : reconnaître une image, traduire un texte, jouer aux échecs, recommander une vidéo. Elle ne « comprend » pas le monde comme un être humain : elle suit des <b>instructions</b> et traite des <b>données</b>.</p>`),
   T('Des IA partout, mais pas magiques',`<p>On trouve de l’IA dans un <b>correcteur orthographique</b>, un <b>GPS</b>, un <b>filtre photo</b>, un <b>assistant vocal</b>. Ces programmes sont créés par des humains, qui choisissent leurs objectifs et les données utilisées pour les entraîner. Une IA n’a ni conscience, ni émotions, ni volonté propre : elle exécute ce pour quoi elle a été conçue.</p>`),
   T('Deux grandes familles',`<p>Certaines IA suivent des <b>règles écrites à l’avance</b> par des humains (« si… alors… »). D’autres <b>apprennent</b> à partir de nombreux exemples (on parle d’<b>apprentissage automatique</b>) : elles repèrent des régularités dans les données plutôt que de suivre des règles toutes faites.</p>`)],
  [{q:'Un correcteur orthographique souligne un mot mal écrit. Est-ce de l’IA ?',s:['Oui : il analyse le texte et applique des règles ou des exemples appris pour détecter une erreur probable.','Il ne « comprend » pas le sens de la phrase comme un humain.','Il peut se tromper (faux positif ou mot correct non reconnu).']}],
  ['Je sais qu’une IA est un programme créé par des humains.','Je distingue une IA à règles et une IA par apprentissage.','Je sais que l’IA traite des données sans « comprendre » comme un humain.','Je repère des exemples d’IA dans mon quotidien.'],
  ['Croire qu’une IA pense et ressent comme un être humain.','Penser qu’une IA fonctionne « par magie », sans données ni programmation.','Oublier qu’une IA peut se tromper.'],
  ['IA = programme pour une tâche « intelligente ».','Règles écrites vs apprentissage automatique.','Pas de conscience ni d’émotions.']),
 g:mix([sort({'Utilise une IA':['un correcteur orthographique','un assistant vocal qui répond à des questions','un filtre qui transforme un visage en photo','un système de recommandation de vidéos'],'N’utilise pas d’IA':['une calculatrice simple à 4 opérations','une lampe à interrupteur','une règle graduée','un livre papier']},{q:'« %s » : avec ou sans IA ?'}),2],
  [bank([
   ['Une intelligence artificielle est…','un programme informatique qui réalise des tâches demandant habituellement de l’intelligence humaine',['une personne très intelligente','un robot avec des sentiments','un ordinateur sans programme'],'Elle reste un programme créé par des humains.'],
   ['Une IA peut-elle ressentir des émotions ?','non',['oui, toujours','oui, si elle est très avancée','oui, comme un humain'],'Elle n’a pas de conscience ni d’émotions.'],
   ['Qui conçoit une intelligence artificielle ?','des humains (chercheurs, ingénieurs)',['elle se crée toute seule','personne, elle existe depuis toujours','uniquement des robots'],'Des choix humains définissent ses objectifs et ses données.'],
   ['Un GPS qui calcule le meilleur trajet utilise…','de l’intelligence artificielle',['uniquement une carte papier','aucune technologie particulière','un simple dessin'],'Il traite des données pour proposer un résultat.'],
   ['Une IA qui apprend à partir de nombreux exemples relève de…','l’apprentissage automatique',['la magie','la chance','l’improvisation'],'Elle repère des régularités dans les données.'],
   ['Une IA à règles fonctionne en suivant…','des instructions écrites à l’avance par des humains (« si… alors… »)',['son propre jugement libre','rien de particulier','des rêves programmés'],'Elle applique des règles définies au préalable.'],
   {tf:'Une intelligence artificielle « comprend » le monde exactement comme un être humain.',v:false,e:'Elle traite des données selon sa conception, sans compréhension consciente.'},
   {tf:'Une IA peut se tromper.',v:true,e:'Elle n’est pas infaillible, qu’elle suive des règles ou qu’elle ait appris par l’exemple.'},
   ['Un filtre photo qui transforme un visage en dessin utilise probablement…','de l’intelligence artificielle',['uniquement une règle graduée','un simple miroir','une calculatrice basique'],'Il analyse l’image pour la transformer.',2]]),2])},

{id:'ia6b',name:'Données, exemples et apprentissage',icon:'📊',domain:'Données',
 refs:[TECH,CRCN,EDU],
 tip:'Pour apprendre à reconnaître des chats sur des photos, une IA a besoin de voir énormément d’exemples de chats (et de non-chats) : plus les exemples sont nombreux et variés, mieux elle généralise.',
 c:C(`Beaucoup d’IA <b>apprennent</b> à partir de <b>données</b> : des exemples, souvent en très grand nombre, qu’on leur montre pour qu’elles repèrent des régularités. Comprendre ce principe aide à comprendre pourquoi une IA réussit bien certaines tâches… et se trompe sur d’autres.`,
  [T('Qu’est-ce qu’une donnée ?',`<p>Une <b>donnée</b> est une information numérique : une photo, un texte, un son, un chiffre. Pour <b>entraîner</b> une IA à reconnaître des chats, on lui montre des milliers de <b>photos</b>, certaines étiquetées « chat », d’autres « pas chat ». L’IA ajuste progressivement son fonctionnement pour mieux distinguer les deux catégories.</p>`),
   T('Pourquoi la quantité et la variété comptent',`<p>Si on entraîne une IA uniquement avec des photos de <b>chats noirs</b>, elle risque de mal reconnaître un chat <b>blanc</b> ou <b>roux</b>. Plus les exemples sont <b>nombreux</b> et <b>variés</b>, mieux l’IA <b>généralise</b> à des cas nouveaux qu’elle n’a jamais vus.</p>`)],
  [{q:'Une IA entraînée uniquement avec des photos de chiens de grande taille a du mal à reconnaître un petit chien. Pourquoi ?',s:['Les exemples utilisés pour l’entraîner manquaient de variété.','Elle n’a pas appris à reconnaître les petits chiens comme une catégorie valide.','Pour corriger cela, il faudrait l’entraîner avec des exemples plus variés (petits et grands chiens).']}],
  ['Je sais qu’une IA apprend à partir d’exemples (données).','Je comprends que la quantité d’exemples influence la qualité de l’apprentissage.','Je comprends que la variété des exemples influence la capacité à généraliser.','Je peux expliquer pourquoi un manque d’exemples cause des erreurs.'],
  ['Croire qu’une IA « sait » sans avoir vu d’exemples.','Penser qu’un seul exemple suffit toujours pour bien apprendre.','Ignorer que des exemples peu variés limitent les capacités de l’IA.'],
  ['Donnée = information numérique (photo, texte, son…).','Entraînement = ajustement à partir d’exemples.','Quantité + variété = meilleure généralisation.']),
 g:mix([d=>{const n=P([50,100,500,1000,5000]);return ch(`Pour reconnaître des pandas sur des photos, une IA a été entraînée avec seulement ${n} photos, toutes prises de face, en pleine lumière. Reconnaîtra-t-elle facilement un panda photographié de côté, dans la pénombre ?`,'probablement moins bien, car ce cas n’était pas représenté dans ses exemples','probablement très bien, car le nombre d’exemples suffit toujours',{expl:'Le manque de variété des exemples (toujours de face, en pleine lumière) limite sa capacité à généraliser à des situations différentes.',hint:'Regarde la variété des exemples, pas seulement leur nombre.'});},2],
  [bank([
   ['Une donnée, pour une IA, est…','une information numérique (photo, texte, son, chiffre…)',['une pensée','un sentiment','une règle de grammaire uniquement'],'C’est la matière première de l’apprentissage automatique.'],
   ['Pour entraîner une IA à reconnaître des chats, on lui montre…','de nombreux exemples de photos étiquetées « chat » ou « pas chat »',['un seul dessin de chat','aucune photo, elle devine seule','une définition écrite du mot « chat »'],'Elle apprend à partir de ces exemples.'],
   ['Pourquoi la variété des exemples d’entraînement est-elle importante ?','elle aide l’IA à généraliser à des cas nouveaux et différents',['elle ralentit toujours l’IA sans aucun bénéfice','elle n’a aucune importance','elle sert uniquement à remplir de la mémoire'],'Sans variété, l’IA reconnaît mal les cas inhabituels.'],
   ['Une IA entraînée uniquement sur des exemples d’un seul type risque de…','mal fonctionner face à des cas différents de ceux appris',['fonctionner parfaitement dans tous les cas','ne jamais se tromper','devenir plus intelligente qu’un humain'],'Elle généralise mal en dehors de ce qu’elle a appris.'],
   ['Généraliser, pour une IA, signifie…','appliquer ce qu’elle a appris à des cas nouveaux, jamais vus pendant l’entraînement',['répéter exactement les exemples appris',' oublier tous les exemples','refuser de répondre à toute nouvelle question'],'C’est l’objectif principal de l’apprentissage automatique.'],
   {tf:'Plus les exemples utilisés pour entraîner une IA sont nombreux et variés, mieux elle peut généraliser.',v:true,e:'C’est un principe de base de l’apprentissage automatique.'},
   {tf:'Une IA entraînée avec très peu d’exemples peu variés fonctionnera aussi bien qu’une IA entraînée avec beaucoup d’exemples variés.',v:false,e:'Le manque de données limite ses capacités.',d:2}]),2])},

{id:'ia6c',name:'Reconnaître les limites et erreurs d’une IA',icon:'⚠️',domain:'Esprit critique',
 refs:[TECH,CRCN,EDU],
 tip:'Une IA peut se tromper avec beaucoup d’assurance : une réponse qui paraît sûre n’est pas forcément exacte — il faut vérifier, comme pour toute information.',
 c:C(`Les IA progressent vite, mais elles ne sont pas <b>parfaites</b>. Elles peuvent se tromper, parfois de façon surprenante, et ne savent pas toujours reconnaître leurs propres <b>limites</b>.`,
  [T('Des erreurs possibles',`<p>Une IA peut mal reconnaître une image dans de mauvaises conditions (lumière, angle inhabituel), mal comprendre une question ambiguë, ou donner une réponse <b>fausse</b> avec une apparence de certitude. Elle peut aussi reproduire des <b>erreurs</b> présentes dans les exemples utilisés pour l’entraîner.</p>`),
   T('Garder un regard critique',`<p>Une réponse d’IA qui semble assurée n’est pas forcément exacte : il faut la <b>vérifier</b>, comme n’importe quelle information (voir les chapitres d’EMI sur la vérification). On ne confie pas à une IA des décisions importantes sans contrôle humain, en particulier pour des sujets sensibles (santé, sécurité).</p>`)],
  [{q:'Un assistant vocal donne une réponse fausse à une question de géographie, avec un ton assuré. Que faire ?',s:['Ne pas croire la réponse simplement parce qu’elle est donnée avec assurance.','Vérifier l’information dans une source fiable (encyclopédie, manuel).','Comprendre qu’une IA peut se tromper sans le signaler elle-même.']}],
  ['Je sais qu’une IA peut se tromper.','Je comprends qu’une réponse assurée n’est pas forcément exacte.','Je vérifie une réponse d’IA importante avant de la croire.','Je comprends qu’une IA peut reproduire les erreurs de ses exemples d’entraînement.'],
  ['Croire automatiquement une réponse d’IA parce qu’elle paraît sûre d’elle.','Confier une décision importante à une IA sans aucun contrôle humain.','Penser qu’une IA reconnaît toujours ses propres erreurs.'],
  ['Erreurs possibles : image mal reconnue, réponse fausse assurée.','Vérifier comme toute information.','Contrôle humain sur les décisions importantes.']),
 g:mix([bank([
  ['Une IA peut-elle donner une réponse fausse avec un ton assuré ?','oui',['non, jamais','non, elle signale toujours son incertitude','non, c’est impossible techniquement'],'L’apparence de certitude ne garantit pas l’exactitude.'],
  ['Pourquoi faut-il vérifier une réponse importante donnée par une IA ?','parce qu’elle peut se tromper sans le signaler',['parce que les IA sont toujours fausses','parce que c’est interdit de l’utiliser','ce n’est jamais nécessaire'],'La vérification reste une bonne habitude, comme pour toute information.'],
  ['Une IA qui reconnaît mal une image dans la pénombre montre…','une limite liée aux conditions différentes de ses exemples d’entraînement',['qu’elle n’a jamais de limite','qu’elle est toujours parfaite','qu’elle a des émotions'],'Les cas inhabituels posent souvent des difficultés.'],
  ['Pour une décision importante (par exemple médicale), faut-il se fier uniquement à une IA ?','non, un contrôle humain reste nécessaire',['oui, toujours et uniquement à elle','oui, car elle ne se trompe jamais sur ce sujet','oui, car c’est plus rapide'],'Les sujets sensibles demandent une vérification humaine.'],
  {tf:'Une intelligence artificielle reconnaît toujours quand elle se trompe et le signale clairement.',v:false,e:'Elle peut donner une réponse fausse sans la signaler comme incertaine.'},
  {tf:'Une IA peut reproduire des erreurs présentes dans les exemples utilisés pour l’entraîner.',v:true,e:'Elle apprend à partir de ces exemples, y compris leurs défauts.',d:2},
  ['Une question formulée de façon ambiguë peut-elle entraîner une réponse d’IA hors sujet ?','oui',['non, l’IA comprend toujours exactement ce qu’on veut dire','non, une IA ne se trompe jamais sur le sens d’une question','non, cela n’arrive qu’avec les humains'],'Une formulation claire aide à obtenir une réponse pertinente.'],
  ['Si deux personnes posent la même question à une IA et obtiennent deux réponses légèrement différentes, cela signifie-t-il forcément qu’une IA « mentait » ?','non, certaines IA peuvent varier légèrement leurs réponses sans que cela soit un mensonge',['oui, c’est toujours un mensonge','oui, cela prouve qu’elle est cassée','oui, une IA ne peut jamais varier ses réponses'],'Certains systèmes ne donnent pas une réponse identique à chaque fois.',2],
  ['Avant de faire confiance à une réponse d’IA sur un sujet important, il est utile de…','comparer avec une source fiable et reconnue',['se fier uniquement à son ton assuré','ne jamais vérifier, ce n’est pas nécessaire','demander à une autre IA identique pour confirmer automatiquement'],'Une source indépendante et reconnue reste le meilleur moyen de vérifier.'],
  ['Une IA d’assistance vocale qui ne comprend pas un accent inhabituel montre…','une limite liée à la diversité des exemples utilisés pour l’entraîner',['qu’elle fonctionne parfaitement dans tous les cas','qu’elle n’a jamais aucune limite','qu’elle a volontairement choisi de ne pas répondre'],'Le manque de diversité dans les exemples peut causer ce type d’erreur.',2],
  ['Un correcteur orthographique qui ne signale pas une faute grammaticale subtile montre…','une limite de ce type de programme face à certains cas particuliers',['qu’il n’existe aucun correcteur fiable','qu’il comprend parfaitement toute la langue française','qu’un correcteur n’est jamais une IA'],'Même les outils très utilisés ont des limites.'],
  ['Observer qu’une IA se trompe parfois aide-t-il à mieux l’utiliser ?','oui, cela encourage à vérifier ses résultats plutôt qu’à lui faire une confiance aveugle',['non, il vaut mieux l’ignorer complètement après une erreur','non, cela ne change rien à son utilisation','non, une seule erreur rend l’outil totalement inutile'],'Connaître ses limites permet un usage plus raisonnable.']]),2])},

{id:'ia6d',name:'Utiliser une IA de façon responsable',icon:'🧭',domain:'Usages responsables',
 refs:[TECH,CRCN,RGPD,EDU],
 tip:'Avant d’utiliser une IA pour un devoir : vérifie les consignes de ton professeur, ne donne pas d’informations personnelles, et vérifie toujours ce qu’elle te répond.',
 c:C(`Utiliser une intelligence artificielle de façon <b>responsable</b> demande quelques réflexes simples : respecter les règles fixées, protéger ses <b>données personnelles</b>, et garder un <b>esprit critique</b> sur ce qu’elle produit.`,
  [T('Respecter les règles',`<p>Chaque professeur peut fixer des règles différentes sur l’usage d’une IA pour un devoir (interdit, autorisé pour certaines étapes, obligatoire…). On respecte ces consignes et on reste <b>honnête</b> : rendre un travail entièrement produit par une IA comme s’il était personnel pose un problème d’honnêteté.</p>`),
   T('Protéger ses données',`<p>On ne donne pas à une IA d’informations <b>personnelles</b> (adresse, nom complet, photos d’autres personnes, mots de passe) : ces informations peuvent être conservées et réutilisées. On garde aussi en tête qu’une réponse d’IA doit être <b>vérifiée</b> avant d’être utilisée (voir le chapitre précédent).</p>`)],
  [{q:'Un élève veut utiliser un assistant IA pour l’aider à comprendre un exercice de mathématiques. Comment faire ?',s:['Vérifier si le professeur autorise cet usage pour ce devoir.','Ne donner aucune information personnelle à l’assistant.','Vérifier les explications données plutôt que les recopier sans comprendre.']}],
  ['Je respecte les règles fixées par mes professeurs.','Je ne donne pas d’informations personnelles à une IA.','Je vérifie les réponses obtenues avant de les utiliser.','Je reste honnête sur ce que j’ai fait moi-même.'],
  ['Rendre un devoir entièrement généré par une IA en le présentant comme personnel.','Donner son adresse ou son nom complet à un assistant IA.','Recopier une réponse d’IA sans la comprendre ni la vérifier.'],
  ['Respecter les consignes du professeur.','Protéger ses données personnelles.','Vérifier et comprendre, pas seulement recopier.']),
 g:mix([bank([
  ['Avant d’utiliser une IA pour un devoir, il faut d’abord…','vérifier les consignes du professeur sur cet usage',['l’utiliser sans aucune limite','demander à un camarade de le faire à sa place','ignorer toute règle'],'Les règles peuvent varier selon le devoir et le professeur.'],
  ['Donner son adresse complète à un assistant IA est…','une information personnelle sensible à éviter de partager',['sans aucun risque','obligatoire pour l’utiliser','recommandé pour un meilleur résultat'],'Ces informations peuvent être conservées et réutilisées.'],
  ['Rendre un devoir entièrement produit par une IA en le présentant comme son propre travail est…','un manque d’honnêteté',['toujours autorisé','sans aucune importance','la meilleure méthode pour progresser'],'Cela ne reflète pas ce que l’élève a réellement compris.'],
  ['Pourquoi vérifier une explication donnée par une IA sur un exercice ?','parce qu’elle peut contenir une erreur',['parce que c’est toujours inutile','parce qu’une IA ne se trompe jamais sur ce sujet','pour perdre du temps'],'La vérification reste une bonne habitude.'],
  {tf:'Utiliser une IA pour s’entraîner, en vérifiant ensuite ce qu’elle propose, peut être une aide utile pour apprendre.',v:true,e:'À condition de comprendre et de vérifier, pas seulement de recopier.'},
  {tf:'Toutes les informations données à une IA disparaissent automatiquement et ne sont jamais conservées.',v:false,e:'Certaines informations peuvent être conservées selon le service utilisé.',d:2},
  ['Partager une photo d’un camarade avec un assistant IA sans son accord est-il respectueux de sa vie privée ?','non',['oui, c’est toujours autorisé','oui, si la photo est jolie','oui, car une IA ne regarde jamais vraiment les photos'],'L’accord de la personne concernée reste nécessaire, même avec une IA.',2],
  ['Si une IA donne une réponse différente de ce que dit ton manuel scolaire, que faire ?','vérifier avec le manuel ou demander à ton professeur',['croire automatiquement l’IA','ignorer le manuel définitivement','ne rien faire'],'Le manuel reste une référence vérifiée à comparer.'],
  ['Utiliser une IA pour comprendre une notion, puis refaire l’exercice soi-même sans l’aide, est…','une bonne façon d’apprendre avec son aide',['interdit dans tous les cas','inutile, il vaut mieux tout recopier','la preuve que l’élève ne sait rien faire'],'Comprendre puis s’exercer seul renforce l’apprentissage.'],
  ['Demander à une IA de donner un avis médical précis pour remplacer la visite chez un médecin est-il raisonnable ?','non, il faut consulter un professionnel de santé pour un vrai diagnostic',['oui, totalement fiable','oui, cela évite toujours un déplacement utile','oui, car l’IA remplace les médecins'],'Les sujets de santé demandent un avis humain qualifié.',2],
  ['Si un professeur interdit l’usage d’une IA pour un devoir précis, un élève doit…','respecter cette consigne pour ce devoir',['l’utiliser quand même en le cachant','demander à un camarade de l’utiliser à sa place','ignorer la consigne car elle ne lui plaît pas'],'Les règles fixées par le professeur s’appliquent à ce devoir.'],
  ['Pourquoi comprendre une explication donnée par une IA, plutôt que la recopier sans la lire, est-il important ?','parce que l’objectif du devoir est d’apprendre, pas seulement de le rendre terminé',['parce que l’IA l’exige explicitement à chaque fois','parce que cela n’a aucune importance pour la suite','parce que recopier est toujours plus rapide et suffisant'],'Comprendre permet de progresser réellement.']]),2])}
]);

MQ.add('ia','5',[
{id:'ia5a',name:'IA générative : texte, image et son',icon:'🎨',domain:'IA générative',
 refs:[TECH,CRCN,EDU],
 tip:'Une IA générative ne « puise » pas une réponse déjà écrite quelque part : elle prédit, mot après mot ou pixel après pixel, ce qui est le plus probable, à partir de ce qu’elle a appris.',
 c:C(`Certaines IA ne se contentent pas de reconnaître ou de classer : elles <b>créent</b> du contenu nouveau — un texte, une image, une musique, une voix. On parle d’<b>IA générative</b>.`,
  [T('Générer du texte, de l’image, du son',`<p>Une IA générative de <b>texte</b> (souvent appelée « modèle de langage ») produit une suite de mots <b>probable</b>, en s’appuyant sur d’énormes quantités de textes appris au préalable. Une IA générative d’<b>image</b> crée une image à partir d’une description. Une IA générative de <b>son</b> ou de <b>voix</b> peut composer une musique ou imiter une voix.</p>`),
   T('Prédire, pas « savoir »',`<p>Ces IA ne « savent » pas au sens où un humain sait : elles <b>prédisent</b> ce qui ressemble le plus à ce qu’on attend, d’après ce qu’elles ont appris. Elles peuvent donc produire un contenu très convaincant… et complètement faux ou incohérent (voir le chapitre sur la vérification).</p>`)],
  [{q:'Un assistant IA écrit un paragraphe sur l’histoire de ta ville, de façon très fluide et détaillée.',s:['Le texte a été généré en prédisant une suite de mots probable, pas « recherché » dans une base de faits vérifiés.','Un texte fluide et détaillé n’est pas forcément exact.','Vérifier les faits avancés reste nécessaire.']}],
  ['Je sais ce qu’est une IA générative.','Je peux citer des exemples (texte, image, son, voix).','Je comprends qu’une IA générative « prédit » plutôt que de « savoir ».','Je comprends qu’un contenu généré peut être convaincant sans être exact.'],
  ['Croire qu’une IA générative puise ses réponses dans une base de faits vérifiés.','Penser qu’un texte fluide est automatiquement exact.','Confondre créer du contenu nouveau et rechercher une information existante.'],
  ['IA générative = crée du contenu nouveau.','Texte, image, son, voix.','Prédiction probable, pas vérité garantie.']),
 g:mix([sort({'IA générative':['un outil qui écrit un texte à partir d’une consigne','un outil qui crée une image à partir d’une description','un outil qui compose une musique originale'],'IA de reconnaissance (pas générative)':['un outil qui identifie un visage sur une photo','un outil qui trie des courriels indésirables','un outil qui reconnaît un objet sur une image']},{q:'« %s » relève d’une…'}),2],
  [bank([
   ['Une IA générative de texte produit sa réponse en…','prédisant une suite de mots probable, à partir de ce qu’elle a appris',['recherchant la réponse exacte dans une encyclopédie vérifiée','copiant toujours un texte déjà existant mot pour mot','devinant totalement au hasard'],'Elle ne « sait » pas au sens humain du terme.'],
   ['Une IA générative d’image crée une image à partir…','d’une description fournie par l’utilisateur',['d’une photo existante obligatoirement modifiée','d’un dessin déjà tout fait','d’aucune information'],'On parle parfois de « texte vers image ».'],
   ['Un texte généré par IA, très fluide et bien écrit, est-il forcément exact ?','non',['oui, toujours','oui, car la fluidité garantit l’exactitude','oui, une IA ne peut jamais se tromper en écrivant bien'],'Fluidité et exactitude sont deux choses différentes.'],
   ['Un modèle de langage est un type d’IA qui…','génère du texte en prédisant des suites de mots probables',['répare des ordinateurs','traduit uniquement des langues anciennes','sert uniquement à calculer des additions'],'C’est une des formes d’IA générative les plus connues.'],
   {tf:'Une IA générative peut produire un contenu convaincant mais entièrement inventé.',v:true,e:'C’est pourquoi la vérification reste indispensable.'},
   {tf:'Une IA générative « sait » les choses exactement comme un humain qui les a apprises à l’école.',v:false,e:'Elle prédit des contenus probables, sans compréhension consciente.'}]),2])},

{id:'ia5b',name:'Écrire une consigne claire à une IA',icon:'✍️',domain:'Interaction',
 refs:[TECH,CRCN,EDU],
 tip:'Une consigne précise (le sujet, le format attendu, le niveau de détail) donne presque toujours un meilleur résultat qu’une demande vague.',
 c:C(`La qualité de la réponse d’une IA générative dépend beaucoup de la <b>consigne</b> (parfois appelée « <b>prompt</b> ») qu’on lui donne. Apprendre à formuler une <b>consigne claire</b> améliore nettement les résultats obtenus.`,
  [T('Ce qui rend une consigne claire',`<p>Une bonne consigne précise : le <b>sujet</b> exact, le <b>format</b> attendu (liste, paragraphe, résumé en 3 phrases), le <b>niveau</b> ou le <b>public</b> visé, et éventuellement des <b>exemples</b>. Une consigne vague (« parle-moi de l’histoire ») donne une réponse générale et peu utile ; une consigne précise (« résume en 5 lignes les causes de tel événement, pour un élève de 5e ») donne un résultat plus exploitable.</p>`),
   T('Ajuster après la première réponse',`<p>Si la réponse ne convient pas, on peut <b>reformuler</b> ou <b>préciser</b> sa demande (« plus court », « avec un exemple », « sans jargon ») plutôt que de l’accepter telle quelle. Cet aller-retour fait partie d’une utilisation efficace d’une IA générative.</p>`)],
  [{q:'Compare deux consignes : « Parle-moi des volcans » et « Explique en 4 phrases simples pourquoi un volcan entre en éruption, pour un élève de 5e ».',s:['La première est vague : le résultat sera général.','La seconde précise le format, le niveau et le sujet exact.','La seconde donnera probablement un résultat plus utile et exploitable.']}],
  ['Je sais préciser le sujet exact dans ma consigne.','Je peux indiquer le format attendu (liste, résumé, longueur).','Je peux préciser le niveau ou le public visé.','Je reformule ma demande si la première réponse ne convient pas.'],
  ['Formuler une consigne trop vague et se contenter d’une réponse générale.','Ne jamais reformuler après une réponse décevante.','Oublier de préciser le format attendu.'],
  ['Consigne claire : sujet, format, niveau.','Exemples utiles pour guider la réponse.','Reformuler si besoin.']),
 g:mix([sort({'Consigne vague':['parle-moi de l’histoire','dis-moi des choses sur les animaux','raconte quelque chose sur la science'],'Consigne précise':['résume en 5 lignes les causes de la Première Guerre mondiale, pour un élève de 3e','liste 3 différences entre un mammifère et un reptile, en une phrase chacune','explique en 4 phrases simples le principe de la photosynthèse']},{q:'« %s » est une…'}),2],
  [bank([
   ['Une consigne précise indique en général…','le sujet exact, le format attendu et le niveau visé',['uniquement un mot-clé sans contexte','rien de particulier','une question la plus courte possible, sans aucun détail'],'Plus d’éléments précis donnent un résultat plus exploitable.'],
   ['Si la réponse d’une IA générative ne convient pas, la bonne pratique est de…','reformuler ou préciser sa demande',['l’accepter telle quelle sans rien changer','abandonner complètement l’outil','recommencer une consigne identique en boucle'],'L’échange peut s’ajuster progressivement.'],
   ['Préciser le public visé (par exemple « pour un élève de 5e ») dans une consigne permet…','d’adapter le niveau de la réponse',['de rendre la réponse plus longue sans raison','de bloquer complètement l’outil','de supprimer la réponse'],'Le niveau de langage et de détail s’ajuste en fonction.'],
   {tf:'Une consigne vague donne en général une réponse plus précise qu’une consigne détaillée.',v:false,e:'C’est généralement l’inverse : la précision aide à obtenir un résultat utile.'},
   {tf:'On peut demander à une IA générative de reformuler sa réponse en plus court ou plus simple.',v:true,e:'L’échange peut s’ajuster progressivement selon le besoin.'},
   ['Donner un exemple du résultat attendu dans sa consigne aide-t-il une IA générative à mieux répondre ?','oui, cela guide le format et le style attendus',['non, un exemple n’a jamais d’effet','non, cela complique toujours inutilement la consigne','non, les exemples sont ignorés systématiquement'],'Un exemple précise concrètement ce qui est recherché.'],
   ['Préciser « en 3 points, sans jargon technique » dans une consigne relève…','du format et du niveau attendus',['d’une information inutile à préciser','d’une donnée personnelle sensible','d’une erreur de formulation'],'Ce sont des précisions utiles pour orienter la réponse.']]),2])},

{id:'ia5c',name:'Vérifier une réponse générée',icon:'🔎',domain:'Esprit critique',
 refs:[TECH,CRCN,EDU],
 tip:'Une « hallucination » d’IA est une information inventée, présentée avec assurance : vérifie toujours une date, un nom, une citation ou une source donnés par une IA, surtout s’ils semblent précis.',
 c:C(`Une IA générative peut produire des <b>réponses fausses</b> avec beaucoup d’assurance : on appelle ce phénomène une <b>hallucination</b>. Savoir le reconnaître et <b>vérifier</b> systématiquement protège contre ce risque.`,
  [T('Les hallucinations',`<p>Une <b>hallucination</b> est une information <b>inventée</b> par une IA générative, présentée comme vraie : une fausse date, un faux nom d’auteur, une <b>citation</b> qui n’existe pas, voire un <b>livre</b> ou une <b>étude</b> totalement fictifs. Plus l’information semble précise (un chiffre exact, une citation entre guillemets), plus elle peut sembler crédible <b>sans l’être</b>.</p>`),
   T('Comment vérifier',`<p>On vérifie une réponse d’IA en la comparant à une <b>source fiable indépendante</b> (manuel, encyclopédie reconnue, site officiel) — la même méthode que pour toute information (voir les chapitres d’EMI). Pour une citation précise, on cherche si elle existe réellement ailleurs, mot pour mot.</p>`)],
  [{q:'Une IA cite : « Selon une étude de 2019 publiée dans telle revue, 73 % des élèves… ». Comment vérifier ?',s:['Chercher si cette étude existe réellement (titre, revue, année).','Si on ne trouve aucune trace de cette étude, s’en méfier fortement.','Ne pas réutiliser ce chiffre sans confirmation indépendante.']}],
  ['Je sais ce qu’est une « hallucination » d’IA.','Je me méfie des informations très précises non vérifiées (dates, chiffres, citations).','Je vérifie une réponse avec une source fiable et indépendante.','Je n’utilise pas un chiffre ou une citation d’IA non confirmés.'],
  ['Croire qu’un chiffre précis donné par une IA est forcément exact.','Réutiliser une citation d’IA sans vérifier qu’elle existe réellement.','Ne jamais comparer une réponse d’IA à une source fiable.'],
  ['Hallucination = information inventée, présentée comme vraie.','Précision apparente ≠ exactitude.','Vérifier avec une source fiable indépendante.']),
 g:mix([bank([
  ['Une « hallucination » d’IA désigne…','une information inventée, présentée comme vraie',['une panne de l’écran','un bug d’affichage uniquement','un type de virus informatique'],'Elle peut concerner une date, un nom, une citation.'],
  ['Une citation très précise, donnée par une IA, entre guillemets, est-elle toujours authentique ?','pas forcément',['oui, toujours','oui, car les guillemets garantissent l’exactitude','oui, aucune vérification n’est nécessaire'],'Une IA peut inventer une citation qui semble réelle.'],
  ['Pour vérifier une information donnée par une IA, la meilleure méthode est de…','la comparer à une source fiable et indépendante',['faire confiance car elle semble précise','demander confirmation à la même IA uniquement','ne jamais vérifier, ce serait inutile'],'C’est la même méthode que pour toute autre information.'],
  ['Si on ne trouve aucune trace d’une étude citée par une IA, il faut…','s’en méfier fortement et ne pas la réutiliser',['la croire quand même','la publier immédiatement','l’inventer à son tour pour compléter'],'L’absence de confirmation est un signal d’alerte.'],
  {tf:'Plus une information donnée par une IA semble précise, plus elle est forcément exacte.',v:false,e:'La précision apparente ne garantit pas l’exactitude.'},
  {tf:'Vérifier une réponse d’IA avec une source fiable indépendante est une bonne habitude.',v:true,e:'C’est la méthode recommandée pour éviter les hallucinations.'},
  ['Une IA qui invente un faux titre de livre et un faux auteur pour appuyer sa réponse commet…','une hallucination',['une simple faute de frappe','une blague volontaire de l’IA','une amélioration du texte'],'C’est une information fictive présentée comme réelle.'],
  ['Demander à la même IA de confirmer sa propre réponse suffit-il à la vérifier de façon fiable ?','non, mieux vaut une source indépendante',['oui, totalement suffisant','oui, car elle corrige toujours ses propres erreurs','oui, cela équivaut à une vérification externe'],'Une IA peut répéter la même erreur en la confirmant elle-même.',2],
  ['Une réponse d’IA qui dit explicitement « je ne suis pas certain » est-elle plus ou moins risquée à utiliser sans vérifier qu’une réponse très affirmative mais fausse ?','une réponse incertaine signalée comme telle est plus facile à traiter avec prudence que la fausse certitude',['les deux sont exactement aussi risquées','la réponse affirmative fausse est toujours plus sûre','l’incertitude signalée est toujours plus dangereuse'],'Une incertitude signalée invite davantage à la vérification.',3],
  ['Pour un exposé scolaire, utiliser une date donnée par une IA sans la confirmer ailleurs est-il prudent ?','non, mieux vaut la confirmer dans un manuel ou une source fiable',['oui, totalement prudent','oui, les dates ne sont jamais inventées par une IA','oui, car un exposé n’a pas besoin d’être exact'],'La vérification protège contre une éventuelle hallucination.'],
  ['Le terme « hallucination » appliqué à une IA est-il identique à une hallucination humaine (perception sans réalité) ?','c’est une métaphore : l’IA ne perçoit rien, elle génère une information fausse',['oui, exactement la même chose vécue consciemment','non, le terme ne s’applique jamais à l’IA','oui, l’IA « voit » réellement des choses fausses'],'Le mot est repris par analogie, sans impliquer de conscience chez l’IA.',3],
  ['Une réponse d’IA à une question factuelle précise (une date, un chiffre) demande-t-elle une vigilance particulière ?','oui, car une erreur y est facilement invisible si elle paraît plausible',['non, ces questions sont toujours traitées sans erreur','non, les chiffres sont toujours vérifiés automatiquement','non, cela ne concerne que les questions d’opinion'],'Les faits précis sont justement ceux où une hallucination passe facilement inaperçue.']]),2])},

{id:'ia5d',name:'Biais et données d’entraînement',icon:'⚖️',domain:'Éthique',
 refs:[TECH,CRCN,EDU],
 tip:'Un biais d’IA ne vient généralement pas d’une intention malveillante des créateurs, mais d’un déséquilibre dans les exemples utilisés pour l’entraîner.',
 c:C(`Une IA entraînée sur des <b>exemples</b> peut reproduire, sans le vouloir, des <b>déséquilibres</b> ou des <b>stéréotypes</b> présents dans ces exemples : on parle de <b>biais</b>. Comprendre ce mécanisme aide à garder un regard critique sur les résultats produits par une IA.`,
  [T('D’où viennent les biais',`<p>Si les <b>données d’entraînement</b> contiennent plus d’exemples d’un type que d’un autre (par exemple, plus de photos de métiers occupés par des hommes que par des femmes dans un jeu de données), l’IA peut <b>reproduire</b> ce déséquilibre dans ses résultats, sans que personne l’ait voulu explicitement.</p>`),
   T('Des conséquences concrètes',`<p>Un système de reconnaissance faciale moins performant sur certains visages, un outil de recommandation d’emploi qui favorise un profil type, une IA générative qui associe systématiquement un métier à un seul genre : ce sont des exemples de biais documentés. Identifier et corriger ces biais fait partie du travail de recherche en IA.</p>`)],
  [{q:'Une IA générative d’images, à qui on demande « un chirurgien », produit presque toujours un homme. Pourquoi ?',s:['Les exemples d’entraînement contenaient probablement plus d’images d’hommes chirurgiens.','L’IA a reproduit ce déséquilibre sans intention explicite.','Ce résultat reflète un biais, pas une règle universelle.']}],
  ['Je comprends qu’un biais vient souvent d’un déséquilibre dans les données d’entraînement.','Je peux citer un exemple de biais d’IA.','Je comprends qu’un biais n’est pas toujours volontaire.','Je garde un regard critique sur les résultats stéréotypés d’une IA.'],
  ['Croire qu’une IA est toujours neutre et objective.','Penser qu’un biais est toujours volontaire de la part des créateurs.','Accepter un résultat stéréotypé sans le questionner.'],
  ['Biais = reproduction d’un déséquilibre des données.','Pas toujours intentionnel.','Exemples : reconnaissance faciale, recommandations, génération d’images.']),
 g:mix([bank([
  ['Un biais d’IA vient souvent…','d’un déséquilibre dans les exemples utilisés pour l’entraîner',['d’une intention toujours malveillante des créateurs','du hasard uniquement','d’un défaut de l’écran'],'Les données reflètent parfois des déséquilibres existants.'],
  ['Une IA d’images qui associe systématiquement un métier à un seul genre montre…','un biais probablement issu de ses données d’entraînement',['une règle universelle toujours vraie','un choix personnel de l’IA','l’absence totale de problème'],'Ce résultat ne reflète pas une vérité générale.'],
  ['Les biais d’IA sont-ils toujours créés intentionnellement ?','non, ils peuvent apparaître sans intention explicite',['oui, toujours volontairement','oui, c’est systématiquement un acte malveillant','oui, cela n’arrive jamais par accident'],'Le déséquilibre des données suffit souvent à les expliquer.'],
  ['Pourquoi est-il important d’identifier les biais d’une IA ?','pour éviter de reproduire ou d’amplifier des stéréotypes injustes',['ce n’est jamais important','pour rendre l’IA plus lente volontairement','pour la rendre payante'],'Cela fait partie d’un usage et d’une conception responsables.'],
  {tf:'Un système de reconnaissance faciale peut être moins performant pour certains types de visages si ses exemples d’entraînement en contenaient peu.',v:true,e:'C’est un exemple documenté de biais par manque de représentativité.'},
  {tf:'Une IA ne peut jamais reproduire un stéréotype, car elle est entièrement neutre par nature.',v:false,e:'Elle peut reproduire les déséquilibres présents dans ses données.'},
  ['Corriger un biais identifié dans une IA demande généralement…','de revoir ou de diversifier les données utilisées pour l’entraîner',['de l’éteindre définitivement sans aucune autre option','rien de particulier, cela se corrige automatiquement','de changer uniquement sa couleur d’interface'],'Le travail sur les données est une piste centrale de correction.',2],
  ['Un biais d’IA peut-il avoir des conséquences concrètes sur des personnes réelles ?','oui, par exemple dans le recrutement ou la reconnaissance faciale',['non, cela reste toujours sans effet réel','non, cela ne concerne que des cas imaginaires','non, les biais n’affectent jamais les décisions prises'],'Des cas documentés montrent des effets concrets et parfois discriminatoires.',2],
  ['Tester une IA avec des exemples variés (profils, origines, situations) avant de l’utiliser largement permet…','de repérer plus facilement des biais éventuels',['de garantir qu’elle n’aura jamais aucun biais','de la rendre automatiquement plus lente sans bénéfice','de supprimer tout intérêt au test'],'Les tests variés aident à détecter des comportements inégaux.',2],
  ['Si une IA de recommandation de métiers propose systématiquement les mêmes types de métiers à un même profil d’élève, cela peut révéler…','un biais lié à ses données d’entraînement ou à ses critères de recommandation',['une vérité universelle sur les capacités de cet élève','un simple hasard sans aucune cause','une preuve que l’IA connaît parfaitement cet élève'],'Un résultat répétitif peut signaler un déséquilibre du système.',3],
  ['Des chercheurs qui publient leurs méthodes pour détecter les biais d’une IA contribuent-ils à un usage plus responsable de cette technologie ?','oui, la transparence aide à identifier et corriger les problèmes',['non, cela n’a aucune utilité pratique','non, cela rend l’IA automatiquement pire','non, ces travaux restent toujours secrets'],'La recherche sur les biais est un axe important et public de ce domaine.'],
  ['Comparer les résultats d’une IA sur différents groupes (par exemple selon l’origine ou le genre des exemples) permet…','de mesurer si elle traite ces groupes de façon équitable',['de prouver automatiquement qu’il n’y a jamais de biais','de rendre la comparaison impossible','de remplacer totalement la notion de biais'],'C’est une méthode utilisée pour évaluer l’équité d’un système.',2]]),2])},

{id:'ia5e',name:'Protéger ses données quand on utilise une IA',icon:'🔒',domain:'Protection',
 refs:[TECH,CRCN,RGPD,EDU],
 tip:'Avant d’envoyer un texte, une photo ou une question à une IA, demande-toi si elle contient une information personnelle (sur toi ou sur d’autres) que tu ne voudrais pas voir conservée ou réutilisée.',
 c:C(`Utiliser une IA, c’est souvent lui <b>envoyer</b> des informations (une question, un texte, une photo). Comprendre ce qui peut arriver à ces informations aide à <b>protéger</b> sa vie privée et celle des autres.`,
  [T('Ce qui peut être conservé',`<p>Selon le service utilisé, les <b>échanges</b> avec une IA peuvent être <b>conservés</b> pour améliorer le service, parfois relus par des humains dans le cadre de contrôles qualité. Certaines IA, selon leurs réglages, peuvent réutiliser ces échanges pour s’<b>entraîner</b> davantage.</p>`),
   T('Bonnes pratiques',`<p>On ne partage pas de <b>données personnelles</b> sensibles (adresse, numéro de téléphone, mot de passe, données de santé) dans une conversation avec une IA. On ne partage pas non plus une <b>photo</b> ou une information sur <b>une autre personne</b> sans son accord. Le <b>RGPD</b> et la <b>CNIL</b> encadrent la collecte et l’usage de ces données, y compris par les services d’IA proposés en Europe.</p>`)],
  [{q:'Un élève veut demander à une IA de corriger une lettre contenant son adresse et son numéro de téléphone.',s:['Il peut retirer ces informations personnelles avant d’envoyer le texte.','Ces données pourraient être conservées par le service.','Mieux vaut les remplacer par des informations fictives pour la correction, puis les remettre ensuite.']}],
  ['Je sais que mes échanges avec une IA peuvent être conservés.','Je ne partage pas d’informations personnelles sensibles avec une IA.','Je ne partage pas d’informations sur d’autres personnes sans leur accord.','Je sais que le RGPD et la CNIL encadrent ces usages.'],
  ['Partager son adresse ou son numéro de téléphone dans une conversation avec une IA.','Partager une photo d’un camarade sans son accord avec une IA.','Croire que tout ce qu’on envoie à une IA disparaît immédiatement.'],
  ['Échanges parfois conservés.','Pas de données sensibles personnelles.','RGPD et CNIL : cadre légal de protection.']),
 g:mix([bank([
  ['Les échanges avec une IA peuvent-ils être conservés par le service utilisé ?','oui, selon les réglages et les conditions d’utilisation',['non, jamais','non, c’est techniquement impossible','non, uniquement si on le demande explicitement'],'Cela dépend du service et de ses paramètres.'],
  ['Partager son numéro de téléphone dans une conversation avec une IA est…','une pratique à éviter',['toujours sans aucun risque','obligatoire pour utiliser l’outil','recommandé pour un meilleur résultat'],'Cette information pourrait être conservée.'],
  ['Le RGPD encadre…','la collecte et l’usage des données personnelles, y compris par les services d’IA',['uniquement les correcteurs orthographiques','uniquement les jeux vidéo','aucun service numérique'],'Il s’applique largement aux services numériques en Europe.'],
  ['Partager une photo d’un camarade avec une IA sans son accord respecte-t-il sa vie privée ?','non',['oui, toujours','oui, si la photo est floue','oui, car une IA ne « voit » jamais vraiment les images'],'L’accord de la personne concernée reste nécessaire.'],
  {tf:'Toutes les informations envoyées à une IA sont automatiquement effacées et jamais conservées.',v:false,e:'Cela dépend du service et de ses conditions d’utilisation.'},
  {tf:'La CNIL veille, en France, au respect des règles de protection des données personnelles, y compris pour les services d’IA.',v:true,e:'Commission nationale de l’informatique et des libertés.',d:2},
  ['Partager une donnée de santé (par exemple un symptôme précis avec son nom complet) dans une conversation avec une IA est…','risqué, car c’est une donnée personnelle particulièrement sensible',['totalement anodin','obligatoire pour obtenir une réponse','sans aucun risque pour la vie privée'],'Les données de santé bénéficient d’une protection renforcée.',2],
  ['Lire les conditions d’utilisation d’un service d’IA avant de l’utiliser régulièrement permet…','de savoir comment les données échangées peuvent être utilisées',['de perdre du temps pour rien','de rendre le service payant automatiquement','de bloquer le service'],'Cela informe sur la conservation et l’usage des données.'],
  ['Utiliser un pseudonyme plutôt que son nom réel lors d’une conversation avec une IA peut-il limiter certains risques pour la vie privée ?','oui, cela réduit le lien direct entre la conversation et l’identité réelle',['non, cela n’a aucun effet','non, cela aggrave toujours le risque','non, un pseudonyme est interdit'],'Cela limite une partie des informations directement identifiantes.',2],
  ['Les conditions d’utilisation d’un service numérique précisent-elles en général comment les données des utilisateurs sont traitées ?','oui, c’est en général l’un de leurs objets principaux',['non, elles ne parlent jamais de ce sujet','non, elles ne concernent que le prix du service','non, elles sont toujours vides de contenu utile'],'Elles encadrent notamment la collecte et l’usage des données.'],
  ['Envoyer à une IA une photo de son propre visage pour « s’amuser » avec un filtre comporte-t-il un enjeu de vie privée ?','oui, certaines données biométriques (visage) sont particulièrement sensibles',['non, aucun enjeu particulier','non, une photo n’est jamais une donnée personnelle','non, cela ne concerne que les adultes'],'Les données biométriques bénéficient d’une protection renforcée.',2],
  ['Un service d’IA gratuit se finance-t-il parfois en partie grâce à l’exploitation des données de ses utilisateurs ?','oui, c’est un modèle économique fréquent pour des services numériques gratuits',['non, jamais','non, la gratuité élimine systématiquement cette possibilité','non, cela ne concerne que les services payants'],'« Si le service est gratuit, les données peuvent faire partie du modèle économique. »',2]]),2])}
]);

MQ.add('ia','4',[
{id:'ia4a',name:'Apprentissage automatique : principe général',icon:'🧠',domain:'Comprendre l’IA',
 refs:[TECH,CRCN,EDU],
 tip:'L’apprentissage automatique fonctionne en trois temps : des données d’entraînement, un modèle qui ajuste ses paramètres pour réduire ses erreurs, puis un test sur des données jamais vues pour vérifier qu’il généralise bien.',
 c:C(`En 4e, on approfondit le fonctionnement de l’<b>apprentissage automatique</b> (machine learning) : comment un programme peut-il « apprendre » à partir de données, sans qu’on lui écrive une règle explicite pour chaque cas ?`,
  [T('Entraînement, modèle, test',`<p>On distingue des <b>données d’entraînement</b> (les exemples utilisés pour apprendre), un <b>modèle</b> (la structure mathématique qui s’ajuste progressivement pour mieux prédire), et des <b>données de test</b> (des exemples <b>jamais vus</b> pendant l’entraînement, utilisés pour vérifier que le modèle généralise bien, et pas seulement qu’il « récite » les exemples appris).</p>`),
   T('Apprentissage supervisé et non supervisé',`<p>Dans l’<b>apprentissage supervisé</b>, chaque exemple est <b>étiqueté</b> (une photo est marquée « chat » ou « chien ») : le modèle apprend à retrouver l’étiquette correcte. Dans l’<b>apprentissage non supervisé</b>, les données ne sont pas étiquetées : le modèle cherche lui-même des <b>regroupements</b> ou des régularités (par exemple, regrouper des clients aux habitudes d’achat similaires).</p>`)],
  [{q:'Pour entraîner une IA à distinguer des photos de pommes et de poires, que faut-il ?',s:['Des données d’entraînement : des photos étiquetées « pomme » ou « poire ».','Un modèle qui ajuste progressivement ses paramètres en comparant ses prédictions aux étiquettes.','Des données de test : de nouvelles photos jamais vues, pour vérifier la généralisation.']}],
  ['Je distingue données d’entraînement et données de test.','Je comprends le rôle du modèle qui s’ajuste progressivement.','Je distingue apprentissage supervisé (données étiquetées) et non supervisé.','Je comprends pourquoi tester sur des exemples jamais vus est essentiel.'],
  ['Confondre « bien réciter les exemples appris » et « bien généraliser ».','Croire que toutes les données doivent être étiquetées pour qu’une IA apprenne.','Oublier de tester un modèle sur des données différentes de celles de l’entraînement.'],
  ['Entraînement → modèle ajusté → test sur données nouvelles.','Supervisé : données étiquetées. Non supervisé : regroupements découverts.','Généraliser ≠ réciter.']),
 g:mix([sort({'Apprentissage supervisé':['des photos d’animaux étiquetées avec leur espèce','des courriels marqués « indésirable » ou « normal »','des radiographies annotées « saine » ou « à examiner »'],'Apprentissage non supervisé':['regrouper des clients selon leurs habitudes d’achat, sans étiquette donnée','regrouper des articles de presse par thème, sans catégorie fournie au départ']},{q:'« %s » relève d’un apprentissage…'}),2],
  [bank([
   ['Les données de test, en apprentissage automatique, servent à…','vérifier que le modèle généralise bien à des cas jamais vus pendant l’entraînement',['entraîner le modèle une deuxième fois','remplacer les données d’entraînement','rien de particulier'],'Elles permettent d’évaluer la performance réelle du modèle.'],
   ['Dans l’apprentissage supervisé, chaque exemple est…','étiqueté avec la bonne réponse attendue',['toujours une image','sans aucune information','toujours un texte'],'L’étiquette guide l’ajustement du modèle.'],
   ['Dans l’apprentissage non supervisé, les données sont…','non étiquetées : le modèle cherche lui-même des régularités',['toutes étiquetées manuellement','inutilisables','toujours fausses'],'Le modèle découvre des structures sans réponse donnée au départ.'],
   ['Pourquoi ne pas se contenter d’évaluer un modèle uniquement sur ses données d’entraînement ?','il pourrait simplement « réciter » ces exemples sans bien généraliser',['ce serait toujours suffisant','les données d’entraînement ne servent à rien d’autre','cela rendrait le modèle plus rapide'],'Le test sur des exemples nouveaux révèle la vraie capacité de généralisation.'],
   ['Un « modèle », en apprentissage automatique, est…','une structure mathématique qui s’ajuste pour mieux prédire',['un robot physique','une photo d’exemple','un simple fichier texte'],'Il contient les paramètres ajustés pendant l’entraînement.'],
   {tf:'Un modèle entraîné peut très bien réussir sur ses exemples d’entraînement tout en généralisant mal à de nouveaux cas.',v:true,e:'C’est pourquoi on teste sur des données séparées.'},
   {tf:'L’apprentissage non supervisé nécessite que chaque exemple soit étiqueté à l’avance.',v:false,e:'C’est justement l’apprentissage supervisé qui nécessite des étiquettes.',d:2}]),2])},

{id:'ia4b',name:'Classification, prédiction et recommandation',icon:'🗂️',domain:'Modèles',
 refs:[TECH,CRCN,EDU],
 tip:'Classer (chat ou chien ?), prédire (quelle sera la demande de glaces demain ?) et recommander (quel film proposer ?) sont trois tâches différentes que des IA peuvent réaliser à partir de données.',
 c:C(`Les systèmes d’IA réalisent souvent l’une de ces trois tâches : <b>classer</b> un élément dans une catégorie, <b>prédire</b> une valeur future, ou <b>recommander</b> un contenu adapté à une personne.`,
  [T('Classification',`<p><b>Classer</b>, c’est attribuer une <b>catégorie</b> à un élément : un courriel est « indésirable » ou « normal », une image est « chat » ou « chien ». Le résultat attendu est une étiquette parmi un ensemble <b>fini</b> de catégories possibles.</p>`),
   T('Prédiction et recommandation',`<p><b>Prédire</b>, c’est estimer une valeur <b>future</b> ou <b>inconnue</b> à partir de données passées (la météo de demain, le prix probable d’un bien). <b>Recommander</b>, c’est proposer à un utilisateur un contenu (film, produit, musique) jugé <b>pertinent</b> pour lui, en s’appuyant sur ses comportements passés ou ceux d’utilisateurs similaires.</p>`)],
  [{q:'Un site de vente en ligne propose : « Les clients qui ont acheté ceci ont aussi acheté… ». À quelle tâche cela correspond-il ?',s:['Il s’agit d’une recommandation.','Elle s’appuie sur les comportements d’achat d’autres utilisateurs.','Son but est de proposer un produit jugé pertinent, pas de garantir un achat futur.']}],
  ['Je distingue classification, prédiction et recommandation.','Je peux donner un exemple de chaque tâche.','Je comprends qu’une classification a un nombre fini de catégories possibles.','Je comprends que la recommandation s’appuie sur des comportements passés.'],
  ['Confondre classer (catégorie) et prédire (valeur future).','Croire qu’une recommandation garantit toujours un bon choix.','Penser que ces trois tâches sont identiques.'],
  ['Classer = attribuer une catégorie.','Prédire = estimer une valeur future.','Recommander = proposer un contenu pertinent.']),
 g:mix([sort({'Classification':['trier un courriel comme « indésirable » ou « normal »','identifier si une image montre un chat ou un chien','détecter si une transaction bancaire est « suspecte » ou « normale »'],'Prédiction':['estimer la demande en glaces de la semaine prochaine','estimer le prix probable d’un logement','estimer la température du lendemain'],'Recommandation':['proposer une musique selon les écoutes précédentes','suggérer un produit selon les achats passés','proposer une vidéo selon l’historique de visionnage']},{q:'« %s » relève de la tâche de…'}),2],
  [bank([
   ['Classer un courriel comme « indésirable » relève de…','la classification',['la prédiction','la recommandation uniquement','aucune de ces tâches'],'Une catégorie, parmi un ensemble fini, est attribuée.'],
   ['Estimer la demande future en un produit à partir des ventes passées relève de…','la prédiction',['la classification uniquement','un simple hasard','une recommandation'],'On estime une valeur encore inconnue.'],
   ['Proposer un film selon l’historique de visionnage relève de…','la recommandation',['la classification uniquement','la prédiction uniquement','aucune tâche d’IA'],'Elle s’appuie sur les comportements observés.'],
   ['Une classification a généralement…','un nombre fini de catégories possibles',['un nombre infini de résultats possibles','toujours une seule réponse possible, sans catégorie','aucune réponse possible'],'Par exemple : « chat » ou « chien », deux catégories.'],
   ['Une recommandation garantit-elle toujours un choix qui plaira réellement à l’utilisateur ?','non, elle propose un contenu jugé probablement pertinent, sans certitude',['oui, toujours à 100 %','oui, car elle connaît parfaitement les goûts futurs','oui, sans aucune marge d’erreur'],'C’est une estimation, pas une garantie.'],
   {tf:'Prédire une valeur future et classer un élément dans une catégorie sont deux tâches identiques.',v:false,e:'Prédire estime une valeur ; classer attribue une catégorie parmi un ensemble fini.'},
   {tf:'Un système de recommandation peut s’appuyer sur les comportements d’autres utilisateurs ayant des goûts similaires.',v:true,e:'C’est un principe fréquent (filtrage dit « collaboratif »).',d:2}]),2])},

{id:'ia4c',name:'Algorithmes de recommandation',icon:'📡',domain:'Plateformes',
 refs:[TECH,CRCN,EDU],
 tip:'Un système de recommandation peut comparer tes comportements à ceux d’autres utilisateurs (« les personnes qui ont aimé X ont aussi aimé Y ») ou analyser les caractéristiques des contenus eux-mêmes (genre musical, catégorie de produit).',
 c:C(`Comment un site de musique, de vidéos ou de vente en ligne choisit-il ce qu’il te propose ? Ces plateformes utilisent des <b>algorithmes de recommandation</b>, qui reposent sur quelques grands principes.`,
  [T('Deux grandes approches',`<p>Le <b>filtrage collaboratif</b> compare les comportements de nombreux utilisateurs : si des personnes aux goûts proches des tiens ont aimé un contenu, il te sera probablement proposé. Le <b>filtrage par contenu</b> analyse les <b>caractéristiques</b> des éléments eux-mêmes (genre musical, catégorie de produit, mots-clés) pour proposer des éléments <b>similaires</b> à ceux que tu as déjà aimés.</p>`),
   T('Combiner les approches',`<p>De nombreuses plateformes combinent plusieurs méthodes pour affiner leurs propositions. L’objectif, du point de vue de l’entreprise, est souvent de maximiser l’<b>engagement</b> (temps passé, achats, clics), ce qui n’est pas toujours exactement la même chose que proposer « le meilleur contenu possible » pour l’utilisateur (voir le chapitre d’EMI sur les bulles de filtres).</p>`)],
  [{q:'Un site de musique te propose un morceau parce que des utilisateurs aux goûts proches des tiens l’ont beaucoup écouté. Quelle approche est utilisée ?',s:['Il s’agit du filtrage collaboratif.','Il compare ton comportement à celui d’autres utilisateurs similaires.','Ce n’est pas une analyse directe des caractéristiques musicales du morceau lui-même.']}],
  ['Je distingue filtrage collaboratif et filtrage par contenu.','Je comprends que les plateformes combinent souvent plusieurs méthodes.','Je comprends l’objectif d’engagement du point de vue de l’entreprise.','Je distingue « ce qui maximise l’engagement » et « ce qui est le plus utile à l’utilisateur ».'],
  ['Confondre filtrage collaboratif et filtrage par contenu.','Croire qu’une recommandation vise toujours uniquement l’intérêt de l’utilisateur.','Penser qu’une seule méthode est utilisée par toutes les plateformes.'],
  ['Filtrage collaboratif : comportements d’autres utilisateurs.','Filtrage par contenu : caractéristiques des éléments.','Objectif d’engagement ≠ toujours « meilleur contenu ».']),
 g:mix([sort({'Filtrage collaboratif':['proposer un film car des utilisateurs aux goûts proches l’ont aimé','proposer un produit car des clients similaires l’ont acheté'],'Filtrage par contenu':['proposer un morceau du même genre musical que ceux déjà écoutés','proposer un article de même catégorie que les achats précédents']},{q:'« %s » relève du filtrage…'}),2],
  [bank([
   ['Le filtrage collaboratif s’appuie sur…','les comportements d’autres utilisateurs aux goûts similaires',['uniquement les caractéristiques techniques du contenu','le hasard total','un classement alphabétique'],'« Les personnes qui ont aimé X ont aussi aimé Y. »'],
   ['Le filtrage par contenu s’appuie sur…','les caractéristiques des éléments eux-mêmes (genre, catégorie, mots-clés)',['uniquement le comportement d’autres utilisateurs','le prix du produit uniquement','la météo du jour'],'Il compare des contenus similaires entre eux.'],
   ['L’objectif principal d’une plateforme avec un système de recommandation est souvent…','de maximiser l’engagement (temps passé, clics, achats)',['uniquement d’informer sans aucun autre but','de ralentir l’utilisateur','de limiter l’usage du service'],'Un objectif économique sous-tend souvent la recommandation.'],
   ['« Maximiser l’engagement » est-ce rigoureusement la même chose que « proposer le contenu le plus utile pour l’utilisateur » ?','pas nécessairement',['oui, toujours exactement la même chose','oui, par définition','oui, cela ne dépend jamais du contexte'],'Ces deux objectifs peuvent diverger dans certains cas.',2],
   ['De nombreuses plateformes utilisent-elles une seule méthode de recommandation, sans jamais en combiner plusieurs ?','non, elles combinent souvent plusieurs approches',['oui, toujours une seule méthode','oui, c’est une règle absolue','oui, cela simplifie toujours tout'],'La combinaison affine généralement les résultats.'],
   {tf:'Un algorithme de recommandation peut s’appuyer à la fois sur le comportement d’autres utilisateurs et sur les caractéristiques des contenus.',v:true,e:'C’est fréquent dans les systèmes combinés.'},
   {tf:'Les systèmes de recommandation visent uniquement l’intérêt de l’utilisateur, jamais celui de l’entreprise qui les conçoit.',v:false,e:'Un objectif économique (engagement) intervient souvent aussi.',d:2},
  ['Un nouvel utilisateur, sans historique de comportement, pose-t-il un défi particulier pour le filtrage collaboratif ?','oui, c’est ce qu’on appelle parfois le « problème du démarrage à froid »',['non, aucun défi particulier','non, le filtrage collaboratif fonctionne identiquement pour tous','non, cela concerne uniquement le filtrage par contenu'],'Sans données sur ses goûts, les comparaisons avec d’autres utilisateurs sont plus difficiles.',3],
  ['Le filtrage par contenu peut-il fonctionner même pour un nouvel utilisateur n’ayant encore noté qu’un seul élément ?','oui, car il s’appuie sur les caractéristiques des éléments, pas sur une communauté d’utilisateurs',['non, il nécessite toujours une grande communauté','non, c’est impossible sans historique','non, il est strictement identique au filtrage collaboratif'],'Il compare les caractéristiques des contenus entre eux.',2]]),2])},

{id:'ia4d',name:'IA générative et modèles de langage',icon:'💬',domain:'IA générative',
 refs:[TECH,CRCN,EDU],
 tip:'Un modèle de langage prédit le mot suivant le plus probable, en tenant compte de tout ce qui a été écrit avant dans la conversation (le « contexte ») : c’est pourquoi une même question peut recevoir des réponses différentes selon ce qui précède.',
 c:C(`Les <b>modèles de langage</b>, qui alimentent de nombreux assistants conversationnels, méritent une compréhension plus précise de leur fonctionnement : comment passent-ils d’un texte d’entrée à une réponse cohérente ?`,
  [T('Prédire le mot suivant',`<p>Un modèle de langage a été entraîné sur d’énormes quantités de <b>textes</b>. À partir d’un texte donné (la <b>consigne</b>, ou « prompt »), il prédit, mot après mot (ou « jeton » après « jeton »), la suite la plus <b>probable</b>, en tenant compte de tout le <b>contexte</b> déjà écrit dans la conversation.</p>`),
   T('Pourquoi ça marche (souvent) bien',`<p>Grâce à l’immense quantité de textes appris, ces prédictions produisent souvent des réponses <b>grammaticalement correctes</b> et <b>cohérentes</b> en apparence. Mais la méthode (prédire le mot suivant probable) n’est pas la même chose que « vérifier des faits » : d’où le risque d’<b>hallucinations</b> déjà vu en 5e (ia5c).</p>`)],
  [{q:'Pourquoi un modèle de langage peut-il écrire un texte très correct grammaticalement, mais contenant une erreur factuelle ?',s:['Il prédit une suite de mots probable, pas un fait vérifié.','La grammaire correcte vient de la quantité de textes appris, pas d’une vérification des faits.','Cohérence du texte et exactitude des faits sont deux choses différentes.']}],
  ['Je comprends le principe de prédiction mot après mot.','Je comprends le rôle du contexte dans une conversation.','Je distingue cohérence grammaticale et exactitude factuelle.','Je fais le lien avec le risque d’hallucination déjà étudié.'],
  ['Croire qu’un texte grammaticalement correct est automatiquement exact.','Oublier que le contexte d’une conversation influence la réponse suivante.','Penser qu’un modèle de langage « vérifie » les faits qu’il écrit.'],
  ['Prédiction mot après mot, selon le contexte.','Cohérence ≠ exactitude.','Lien avec les hallucinations (ia5c).']),
 g:mix([bank([
  ['Un modèle de langage génère sa réponse en…','prédisant le mot suivant le plus probable, selon le contexte',['recherchant la réponse dans une base de faits vérifiés','copiant toujours un texte préexistant à l’identique','tirant au hasard chaque mot sans aucun lien avec les autres'],'Cette méthode explique sa fluidité, mais pas une garantie de vérité.'],
  ['Le « contexte », pour un modèle de langage, désigne…','tout ce qui a été écrit avant dans la conversation en cours',['uniquement le premier mot de la phrase','une information totalement indépendante de la conversation','la météo du jour'],'Il influence la suite de mots prédite.'],
  ['Un texte grammaticalement correct écrit par une IA est-il nécessairement exact sur le plan factuel ?','non',['oui, toujours','oui, car la grammaire garantit l’exactitude','oui, cela ne peut jamais être faux'],'Cohérence linguistique et exactitude des faits sont deux choses différentes.'],
  ['Pourquoi une même question peut-elle recevoir des réponses différentes d’un modèle de langage selon le contexte de la conversation ?','parce que la prédiction du mot suivant dépend de tout ce qui précède',['parce que le modèle change totalement de nature','parce que la question elle-même change','parce que cela n’arrive jamais en réalité'],'Le contexte influence directement la génération.',2],
  {tf:'La quantité de textes appris par un modèle de langage explique en partie pourquoi ses réponses semblent souvent cohérentes.',v:true,e:'Il a vu énormément d’exemples de structures de phrases correctes.'},
  {tf:'Un modèle de langage vérifie systématiquement l’exactitude de chaque fait avant de l’écrire.',v:false,e:'Il prédit une suite probable, sans mécanisme de vérification factuelle garanti.',d:2},
  ['Un modèle de langage entraîné sur des textes majoritairement dans une langue répondra-t-il aussi bien dans une langue très peu représentée dans ses données ?','probablement moins bien, par manque d’exemples suffisants',['exactement aussi bien, dans tous les cas','mieux, car moins de données signifie moins d’erreurs','cela n’a aucun rapport avec les données d’entraînement'],'La quantité de textes appris dans une langue influence la qualité des réponses.',2],
  ['Si on change une seule phrase au début d’une longue conversation avec une IA, la suite générée peut-elle changer ?','oui, car le contexte entier influence chaque nouvelle prédiction',['non, jamais','non, seule la dernière phrase compte','non, le début n’a aucune influence'],'Le modèle tient compte de tout l’historique de la conversation.',3],
  ['Un modèle de langage peut-il produire un texte poétique cohérent sans « comprendre » la poésie au sens humain ?','oui, en s’appuyant sur des structures apprises dans de nombreux textes similaires',['non, c’est impossible sans compréhension consciente','non, la poésie ne peut jamais être générée','non, cela nécessite obligatoirement des émotions réelles'],'La prédiction statistique peut reproduire des structures stylistiques apprises.',2],
  ['Deux modèles de langage entraînés sur des données différentes donneront-ils nécessairement des réponses identiques à la même question ?','non, leurs réponses peuvent différer selon leurs données et leur conception',['oui, toujours rigoureusement identiques','oui, car tous les modèles sont construits de la même façon','oui, le contexte n’a aucune influence sur ce point'],'Les données et la conception de chaque modèle influencent ses réponses.'],
  ['Une réponse générée phrase par phrase peut-elle sembler cohérente au début puis s’éloigner progressivement du sujet initial ?','oui, car chaque mot prédit dépend des précédents, et de petits écarts peuvent s’accumuler',['non, la cohérence est toujours garantie du début à la fin','non, cela ne se produit jamais en pratique','non, le sujet initial ne peut jamais être perdu'],'Un enchaînement de prédictions peut progressivement dériver.',3],
  ['Poser une question très courte et vague à un modèle de langage, sans aucun contexte, donne-t-il en général une réponse aussi ciblée qu’une question précise et contextualisée ?','non, en général une question précise et contextualisée donne un résultat plus ciblé',['oui, exactement aussi ciblée dans tous les cas','oui, le contexte n’influence jamais la précision de la réponse','oui, une question vague est toujours préférable'],'Le contexte fourni oriente la prédiction vers un résultat plus pertinent.']]),2])},

{id:'ia4e',name:'Prompt, contexte et critères de qualité',icon:'🎯',domain:'Interaction',
 refs:[TECH,CRCN,EDU],
 tip:'Un bon prompt (consigne) précise le rôle attendu de l’IA, le format de sortie, le niveau de détail et, si besoin, des contraintes (longueur, style, exemples) : plus ces éléments sont explicites, plus le résultat correspond à l’attente.',
 c:C(`En 4e, on approfondit les techniques pour obtenir de meilleurs résultats d’une IA générative : construire un <b>prompt</b> (consigne) efficace et savoir évaluer la <b>qualité</b> d’une réponse selon des critères précis.`,
  [T('Construire un bon prompt',`<p>Un prompt efficace précise souvent : le <b>rôle</b> ou le point de vue attendu (« explique comme à un enfant de 8 ans », « réponds comme un expert »), le <b>format</b> de sortie (liste, tableau, résumé en 3 points), des <b>contraintes</b> (longueur maximale, style, mots à éviter), et parfois un ou plusieurs <b>exemples</b> du résultat souhaité.</p>`),
   T('Évaluer la qualité d’une réponse',`<p>On peut juger une réponse générée selon plusieurs critères : <b>exactitude</b> (les faits sont-ils vérifiables ?), <b>pertinence</b> (répond-elle vraiment à la question posée ?), <b>clarté</b> (est-elle compréhensible ?), et <b>complétude</b> (manque-t-il des éléments importants ?). Une réponse peut être claire et bien écrite tout en étant inexacte ou incomplète.</p>`)],
  [{q:'Évalue cette consigne : « Explique la photosynthèse en 3 phrases simples, pour un élève de 4e, sans jargon technique. »',s:['Elle précise le sujet, le format (3 phrases), le niveau (4e) et une contrainte (sans jargon).','C’est une consigne précise qui devrait donner un résultat exploitable.','On pourra ensuite évaluer la réponse selon l’exactitude, la clarté et la complétude.']}],
  ['Je sais construire un prompt précisant rôle, format et contraintes.','Je peux ajouter un exemple pour guider la réponse attendue.','Je sais évaluer une réponse selon exactitude, pertinence, clarté et complétude.','Je comprends qu’une réponse claire n’est pas forcément exacte ou complète.'],
  ['Formuler un prompt sans aucune précision de format ni de contrainte.','Juger une réponse uniquement sur sa clarté, sans vérifier son exactitude.','Oublier de vérifier si la réponse répond vraiment à la question posée.'],
  ['Prompt : rôle, format, contraintes, exemples.','Qualité : exactitude, pertinence, clarté, complétude.','Clarté ≠ exactitude.']),
 g:mix([sort({'Élément d’un bon prompt':['préciser le format attendu (liste, résumé, tableau)','indiquer le niveau souhaité ou le public visé','donner un exemple du résultat souhaité'],'Critère d’évaluation d’une réponse':['vérifier que les faits avancés sont exacts','vérifier que la réponse répond bien à la question posée','vérifier qu’aucune information importante ne manque']},{q:'« %s » est plutôt…'}),2],
  [bank([
   ['Préciser « réponds en 3 points, sans jargon » dans un prompt relève…','d’une contrainte de format et de style',['d’une donnée personnelle','d’une erreur de formulation','d’un critère d’évaluation de la réponse'],'C’est une précision donnée en amont, pas une évaluation après coup.'],
   ['La « pertinence » d’une réponse évalue…','si elle répond vraiment à la question posée',['sa longueur uniquement','sa couleur d’affichage','le temps mis pour la générer'],'Une réponse peut être bien écrite sans répondre à la vraie question.'],
   ['Une réponse peut-elle être claire et bien écrite tout en étant factuellement inexacte ?','oui',['non, jamais','non, la clarté garantit toujours l’exactitude','non, c’est impossible par définition'],'Clarté et exactitude sont deux critères indépendants.'],
   ['La « complétude » d’une réponse évalue…','si des éléments importants ne manquent pas',['sa couleur','sa vitesse de génération','son origine géographique'],'Une réponse incomplète peut donner une impression trompeuse.'],
   ['Donner un exemple du résultat attendu dans un prompt sert à…','guider plus précisément le format et le style de la réponse',['rendre la consigne invalide','ralentir volontairement l’IA','remplacer totalement la consigne'],'Un exemple concret précise l’attente.'],
   {tf:'Un prompt précis (rôle, format, contraintes) donne généralement un résultat plus exploitable qu’un prompt vague.',v:true,e:'La précision guide la génération.'},
   {tf:'Évaluer une réponse d’IA uniquement sur sa clarté suffit à garantir qu’elle est exacte et complète.',v:false,e:'L’exactitude et la complétude sont des critères distincts à vérifier séparément.',d:2}]),2])},

{id:'ia4f',name:'Biais, stéréotypes et équité',icon:'⚖️',domain:'Éthique',
 refs:[TECH,CRCN,EDU],
 tip:'L’équité d’une IA ne se mesure pas seulement à sa performance globale, mais aussi à sa performance comparée entre différents groupes : une IA peut être globalement précise tout en étant nettement moins précise pour un groupe en particulier.',
 c:C(`En 4e, on approfondit la notion de <b>biais</b> déjà vue en 5e (ia5d), en l’articulant avec celle d’<b>équité</b> : comment évaluer et limiter les traitements inégaux que peut produire une IA entre différents groupes de personnes ?`,
  [T('Mesurer l’équité',`<p>Une IA peut avoir une bonne <b>performance globale</b> (par exemple 95 % de bonnes réponses en moyenne) tout en étant beaucoup moins performante pour un <b>sous-groupe</b> particulier (par exemple un certain type de visage pour la reconnaissance faciale). L’<b>équité</b> consiste à vérifier que les performances restent comparables entre les groupes, pas seulement en moyenne.</p>`),
   T('Des causes et des pistes de correction',`<p>Les causes principales restent les mêmes qu’en 5e : un <b>déséquilibre</b> dans les données d’entraînement. Les pistes de correction incluent : <b>diversifier</b> les données, <b>tester</b> spécifiquement les performances par sous-groupe, et faire <b>auditer</b> le système par des personnes extérieures à l’équipe qui l’a conçu.</p>`)],
  [{q:'Un système de recrutement automatisé réussit en moyenne à bien trier les candidatures, mais défavorise un groupe particulier de candidats. Que faire ?',s:['Mesurer les performances séparément pour chaque groupe, pas seulement en moyenne.','Identifier si les données d’entraînement reflétaient un déséquilibre passé.','Corriger les données ou les critères, et faire auditer le système.']}],
  ['Je comprends qu’une bonne performance moyenne peut cacher une inégalité entre groupes.','Je sais que le déséquilibre des données reste la cause principale des biais.','Je connais des pistes de correction (diversifier, tester par groupe, auditer).','Je mesure l’équité, pas seulement la performance globale.'],
  ['Se contenter d’une performance globale moyenne sans vérifier par sous-groupe.','Croire qu’un biais se corrige tout seul sans action particulière.','Ignorer l’intérêt d’un audit extérieur.'],
  ['Équité = performances comparables entre groupes, pas seulement en moyenne.','Cause principale : déséquilibre des données.','Correction : diversifier, tester, auditer.']),
 g:mix([d=>{const g1=R(85,98),diff=R(10,30),g2=Math.max(40,g1-diff);return ch(`Un système de reconnaissance faciale réussit en moyenne ${g1} % des identifications sur l’ensemble des utilisateurs testés. Pour un sous-groupe particulier, il ne réussit que ${g2} %. Peut-on dire que ce système est équitable entre les groupes ?`,'Non',['Oui'],{expl:`Un écart important entre ${g1} % (moyenne) et ${g2} % (sous-groupe) révèle un traitement inégal : l’équité ne se mesure pas uniquement par la moyenne globale.`,hint:'Compare la moyenne globale à la performance du sous-groupe.'});},2],
  [bank([
   ['L’équité d’un système d’IA se mesure…','en comparant ses performances entre différents groupes, pas seulement en moyenne',['uniquement par sa performance moyenne globale','uniquement par sa rapidité d’exécution','uniquement par son coût de fabrication'],'Une bonne moyenne peut cacher une forte inégalité entre groupes.'],
   ['Un audit externe d’un système d’IA consiste à…','le faire examiner par des personnes extérieures à l’équipe qui l’a conçu',['le faire tester uniquement par ses créateurs','l’éteindre définitivement','changer son nom'],'Un regard extérieur peut repérer des biais non vus par les concepteurs.'],
   ['Diversifier les données d’entraînement peut-il aider à réduire un biais ?','oui, en général',['non, jamais','non, cela aggrave toujours le problème','non, cela n’a aucun effet'],'Des exemples plus représentatifs réduisent les déséquilibres.'],
   ['Un système qui favorise un groupe par rapport à un autre, pour un motif qui n’a rien à voir avec la tâche à accomplir, est…','potentiellement discriminatoire',['toujours parfaitement justifié','sans aucune conséquence','une preuve de bon fonctionnement'],'Ce type de traitement inégal pose un problème d’équité.'],
   {tf:'Une IA peut avoir une bonne performance moyenne tout en étant nettement moins fiable pour un groupe particulier.',v:true,e:'C’est précisément ce que mesure l’analyse par sous-groupe.'},
   {tf:'Un biais d’IA, une fois identifié, ne peut jamais être corrigé.',v:false,e:'Diversifier les données et ajuster le système sont des pistes de correction possibles.',d:2},
   ['Comparer les taux d’erreur d’un système pour différents groupes d’âge, de genre ou d’origine fait partie…','d’une démarche d’évaluation de l’équité du système',['d’une démarche totalement inutile','d’une violation systématique de la loi','d’une opération impossible techniquement'],'C’est une méthode courante d’audit des systèmes d’IA.',2],
   ['Un modèle entraîné presque uniquement sur des données concernant un seul pays peut-il être moins fiable ailleurs dans le monde ?','oui, par manque de représentativité des situations locales',['non, jamais','non, un modèle fonctionne identiquement partout dans le monde','non, la géographie n’a aucune influence'],'Les particularités locales absentes des données peuvent être mal traitées.',3]]),2])},

{id:'ia4g',name:'Droit d’auteur, sources et traçabilité',icon:'©️',domain:'Droit',
 refs:[TECH,CRCN,CPI,EDU],
 tip:'Un contenu généré par IA s’inspire de ses données d’entraînement, qui comprennent souvent des œuvres protégées par le droit d’auteur : la question de savoir qui détient les droits sur un contenu généré, et dans quelles conditions on peut l’utiliser, reste en partie débattue et encadrée différemment selon les pays.',
 c:C(`Les IA génératives apprennent à partir d’énormes quantités de textes, images ou musiques, souvent <b>protégés</b> par le droit d’auteur. Cela pose des questions juridiques et éthiques sur la <b>traçabilité</b> des contenus utilisés et sur les <b>droits</b> liés aux contenus générés.`,
  [T('D’où viennent les données d’entraînement',`<p>Les modèles d’IA générative sont souvent entraînés sur de vastes ensembles de données collectées sur Internet, qui peuvent inclure des <b>œuvres protégées</b> (textes d’auteurs, images d’illustrateurs, musiques de compositeurs), parfois sans l’<b>accord explicite</b> de leurs créateurs. Cette pratique fait l’objet de débats et de procédures judiciaires dans plusieurs pays.</p>`),
   T('Utiliser un contenu généré',`<p>Les règles sur les droits d’un contenu <b>généré par IA</b> (peut-on le vendre ? le republier ? qui en est l’auteur ?) varient selon les pays et évoluent encore. Par prudence : on vérifie les <b>conditions d’utilisation</b> du service d’IA utilisé, et on évite de présenter un contenu généré comme une création personnelle sans le mentionner, en particulier pour un usage scolaire ou professionnel.</p>`)],
  [{q:'Un élève utilise une IA générative d’images pour illustrer un exposé, puis le rend sans mentionner l’usage de l’IA.',s:['Préciser que l’illustration a été générée par une IA est une question de transparence et d’honnêteté.','Les conditions d’utilisation du service d’IA peuvent préciser les droits sur l’image générée.','Dans le doute, mentionner clairement l’origine de l’image reste la pratique la plus prudente.']}],
  ['Je sais que les IA génératives apprennent sur des données pouvant inclure des œuvres protégées.','Je comprends que ce sujet fait l’objet de débats juridiques encore en cours.','Je vérifie les conditions d’utilisation d’un service pour les droits sur un contenu généré.','Je mentionne l’usage d’une IA par transparence, notamment pour un travail scolaire.'],
  ['Croire que toutes les données d’entraînement d’une IA sont automatiquement libres de droits.','Présenter un contenu généré par IA comme une création entièrement personnelle sans le préciser.','Ignorer les conditions d’utilisation d’un service avant de réutiliser un contenu généré.'],
  ['Données d’entraînement : parfois des œuvres protégées, sans accord systématique.','Droits sur un contenu généré : variables selon les pays, encore débattus.','Transparence recommandée sur l’usage de l’IA.']),
 g:mix([bank([
  ['Les données d’entraînement d’une IA générative peuvent-elles inclure des œuvres protégées par le droit d’auteur ?','oui, c’est fréquent, ce qui pose des questions juridiques',['non, jamais','non, c’est techniquement impossible','non, la loi l’interdit systématiquement dans tous les pays'],'Cette question fait l’objet de débats et de procédures en cours.'],
  ['Les règles sur les droits d’un contenu généré par IA sont-elles identiques et définitives dans tous les pays ?','non, elles varient et évoluent encore',['oui, parfaitement identiques partout','oui, elles ne changeront jamais','oui, il n’existe aucune différence entre pays'],'Le cadre juridique est encore en construction dans plusieurs pays.'],
  ['Mentionner qu’une illustration d’un exposé a été générée par une IA relève…','d’une démarche de transparence et d’honnêteté',['d’une obligation légale identique partout','d’une pratique inutile','d’une erreur à éviter'],'C’est une bonne pratique, même sans obligation légale uniforme.'],
  ['Avant de réutiliser un contenu généré par IA pour un usage précis, il est prudent de…','vérifier les conditions d’utilisation du service concerné',['ne vérifier rien du tout','supposer que tout usage est automatiquement autorisé','supposer que tout usage est automatiquement interdit'],'Les conditions précisent souvent les droits accordés.'],
  {tf:'La question des droits sur les contenus générés par IA est un sujet juridique encore débattu dans plusieurs pays.',v:true,e:'Ce domaine évolue rapidement.'},
  {tf:'Utiliser une œuvre protégée pour entraîner une IA ne pose jamais aucune question de droit d’auteur.',v:false,e:'Cette pratique fait au contraire l’objet de débats et de procédures juridiques.',d:2},
  ['Des auteurs et des illustrateurs ont-ils engagé des actions en justice contre certaines entreprises d’IA au sujet de l’utilisation de leurs œuvres ?','oui, plusieurs procédures de ce type existent dans différents pays',['non, jamais, ce sujet n’a suscité aucune action','non, c’est juridiquement impossible','non, cela ne concerne aucun secteur créatif'],'Ces procédures illustrent le débat juridique en cours.',3],
  ['Peut-on, en général, savoir avec certitude et précision quelles œuvres précises ont influencé une réponse donnée par une IA générative ?','c’est généralement difficile à déterminer précisément',['oui, systématiquement et facilement','oui, chaque réponse liste toujours ses sources exactes','oui, car l’IA le précise toujours clairement'],'La traçabilité exacte des influences reste un défi technique.',3],
  ['Le terme « traçabilité », appliqué aux données d’une IA, désigne…','la capacité à savoir d’où viennent les données utilisées pour l’entraîner',['la vitesse d’exécution du programme','la couleur de l’interface utilisateur','le prix du service'],'C’est un enjeu de transparence important.',2],
  ['Certaines entreprises proposent-elles des services d’IA générative entraînés uniquement sur des contenus dont elles détiennent les droits ou sous licence autorisée ?','oui, certaines approches cherchent à limiter ce risque juridique',['non, cela n’existe pas','non, c’est techniquement impossible','non, aucune entreprise ne s’en préoccupe'],'Des approches alternatives à l’entraînement sur données libres de droits existent.',3],
  ['Le fait qu’un contenu généré par IA « ressemble » au style d’un auteur précis, sans le copier mot pour mot, soulève-t-il une question de droit d’auteur ?','c’est une question débattue, notamment pour les styles très reconnaissables',['non, aucune question ne se pose jamais dans ce cas','non, seule la copie mot pour mot pose un problème','non, le style n’a jamais aucune valeur juridique'],'L’imitation de style fait partie des débats actuels sur le sujet.',3],
  ['Un illustrateur qui découvre qu’une IA a été entraînée sur ses œuvres sans son accord peut-il exprimer son désaccord publiquement ou par voie légale ?','oui, plusieurs créateurs l’ont fait dans différents pays',['non, cela ne lui est jamais permis','non, aucun créateur ne s’en préoccupe jamais','non, cela n’a aucune conséquence possible'],'Des créateurs ont engagé des démarches publiques ou juridiques sur ce sujet.',2]]),2])},

{id:'ia4h',name:'Projet : utiliser l’IA avec méthode et esprit critique',icon:'📋',domain:'Projet',
 refs:[TECH,CRCN,PIXIA,EDU],
 tip:'Une démarche responsable avec une IA suit un cycle simple : préciser son besoin (prompt clair), obtenir une réponse, la vérifier avec une source indépendante, puis l’utiliser en la comprenant et en citant son usage si besoin.',
 c:C(`En 4e, le programme comprend des <b>parcours Pix obligatoires sur l’IA</b> (voir pix4h). Ce chapitre synthétise, sous forme de <b>démarche de projet</b>, les connaissances acquises sur l’IA pour les mettre en pratique de façon méthodique et responsable.`,
  [T('Une démarche en quatre étapes',`<p>1. <b>Préciser son besoin</b> : formuler une consigne claire (voir ia5b, ia4e). 2. <b>Obtenir une réponse</b> et l’examiner. 3. <b>Vérifier</b> les informations importantes avec une source indépendante (voir ia5c). 4. <b>Utiliser</b> le résultat en le comprenant, en respectant les règles fixées (voir ia6d) et en mentionnant l’usage de l’IA si le contexte le demande (voir ia4g).</p>`),
   T('Garder une vue d’ensemble',`<p>Cette démarche mobilise les connaissances des chapitres précédents : comprendre le <b>fonctionnement</b> d’une IA (ia6a, ia4a), connaître ses <b>limites</b> (ia6c, ia5c), repérer d’éventuels <b>biais</b> (ia5d, ia4f), et protéger ses <b>données</b> (ia5e). Un usage responsable combine ces différentes vigilances.</p>`)],
  [{q:'Pour un exposé, un élève veut utiliser une IA afin de comprendre un phénomène scientifique complexe.',s:['Il formule une consigne précise, adaptée à son niveau.','Il vérifie les informations importantes dans son manuel ou une source fiable.','Il reformule avec ses propres mots dans son exposé, en comprenant ce qu’il présente.']}],
  ['Je sais formuler une consigne précise pour mon besoin.','Je vérifie les informations importantes obtenues.','Je comprends ce que j’utilise, plutôt que de le recopier sans réfléchir.','Je respecte les règles fixées et je reste transparent sur mon usage si besoin.'],
  ['Utiliser une IA sans formuler de besoin précis.','Ne jamais vérifier les informations obtenues.','Recopier sans comprendre, ou cacher l’usage de l’IA quand la transparence est attendue.'],
  ['Préciser, obtenir, vérifier, utiliser en comprenant.','Mobilise fonctionnement, limites, biais, protection des données.','Respect des règles et transparence.']),
 g:mix([d=>order('Remets dans l’ordre une démarche responsable d’utilisation d’une IA pour un travail scolaire :',['Préciser son besoin avec une consigne claire','Obtenir une réponse et l’examiner','Vérifier les informations importantes avec une source indépendante','Utiliser le résultat en le comprenant et en respectant les règles fixées'],{expl:'Préciser → obtenir → vérifier → utiliser en comprenant.'}),2],
  [bank([
   ['La première étape d’une démarche responsable avec une IA est…','préciser son besoin avec une consigne claire',['vérifier immédiatement une réponse qui n’existe pas encore','utiliser le résultat sans l’avoir obtenu','ignorer complètement la consigne'],'On ne peut pas vérifier une réponse avant de l’avoir obtenue.'],
   ['Pourquoi vérifier les informations importantes obtenues d’une IA avant de les utiliser ?','parce qu’une IA peut se tromper ou halluciner une information',['ce n’est jamais nécessaire','parce que l’IA le signale toujours elle-même clairement','parce que la vérification est interdite'],'La vérification protège contre les erreurs possibles.'],
   ['« Utiliser le résultat en le comprenant » signifie notamment…','ne pas simplement recopier sans réfléchir au contenu',['recopier le plus rapidement possible sans aucune lecture','ignorer entièrement le résultat obtenu','le mémoriser par cœur sans le comprendre'],'La compréhension reste l’objectif d’un travail scolaire.'],
   ['Une démarche responsable avec une IA mobilise notamment la connaissance de…','ses limites et de ses biais possibles',['uniquement son prix d’achat','uniquement sa couleur d’interface','uniquement sa date de sortie'],'Ces connaissances permettent un usage plus prudent et efficace.'],
   {tf:'Une démarche responsable avec une IA combine plusieurs vigilances : consigne claire, vérification, compréhension, respect des règles.',v:true,e:'Ces étapes se complètent.'},
   {tf:'Une fois qu’on a obtenu une réponse d’une IA, il n’y a plus besoin de la vérifier avant de l’utiliser pour un travail important.',v:false,e:'La vérification reste une étape essentielle, en particulier pour un travail important.',d:2},
   ['Si une consigne donnée à une IA n’apporte pas le résultat attendu, la démarche la plus adaptée est…','reformuler la consigne plutôt que d’abandonner immédiatement',['abandonner définitivement l’outil après un seul essai','accepter le résultat tel quel sans aucun ajustement','recommencer exactement la même consigne en boucle sans la changer'],'L’ajustement de la consigne fait partie d’une utilisation efficace.'],
   ['Un projet utilisant une IA peut-il aussi mobiliser des connaissances vues dans d’autres matières (sciences, français) ?','oui, la vérification et la rédaction d’un résultat font appel à des compétences transversales',['non, ces connaissances ne servent jamais ensemble','non, un projet avec IA est complètement isolé des autres matières','non, la vérification des faits n’a aucun lien avec les sciences'],'Les compétences se complètent dans un projet concret.'],
   ['Présenter, à la fin d’un projet, les limites rencontrées (erreurs détectées, biais observés) est-il utile ?','oui, cela montre une réflexion critique sur l’outil utilisé',['non, il faut toujours cacher les difficultés rencontrées','non, cela n’apporte jamais rien au travail final','non, une IA ne présente jamais aucune limite à signaler'],'La réflexion critique fait partie de la démarche de projet.'],
   ['Comparer les résultats obtenus avec une IA à ceux obtenus par une méthode « classique » (manuel, recherche personnelle) peut-il enrichir un projet ?','oui, cela permet de mesurer les apports et les limites de chaque méthode',['non, cela n’a aucun intérêt','non, une seule méthode doit toujours être utilisée','non, cela rend le projet incohérent'],'La comparaison nourrit une réflexion méthodologique.'],
   ['Un élève qui documente, étape par étape, comment il a utilisé une IA dans son projet fait preuve de…','rigueur méthodologique et de transparence',['d’un manque de confiance en lui sans fondement','d’une perte de temps totalement inutile','d’un non-respect des règles, systématiquement'],'Documenter sa démarche aide à expliquer et justifier son travail.']]),2])}
]);

MQ.add('ia','3',[
{id:'ia3a',name:'Données, modèles et entraînement',icon:'📐',domain:'Comprendre l’IA',
 refs:[TECH,CRCN,EDU],
 tip:'Un modèle « surajusté » (overfitting) excelle sur ses exemples d’entraînement mais échoue sur des cas nouveaux, comme un élève qui aurait appris par cœur les exercices d’un cahier sans comprendre la méthode.',
 c:C(`En 3e, on approfondit un défi central de l’apprentissage automatique, déjà abordé en 4e (ia4a) : comment s’assurer qu’un modèle <b>généralise</b> bien, sans « réciter » simplement ses exemples d’entraînement ?`,
  [T('Sous-ajustement et surajustement',`<p>Un modèle en <b>sous-ajustement</b> (underfitting) est trop simple : il ne capture pas assez les régularités des données, et se trompe même sur ses exemples d’entraînement. Un modèle en <b>surajustement</b> (overfitting) est, à l’inverse, trop collé à ses exemples : il les réussit parfaitement, mais généralise mal à des cas nouveaux, un peu comme un élève qui aurait appris par cœur les énoncés d’un cahier d’exercices sans comprendre la méthode.</p>`),
   T('Trouver le bon équilibre',`<p>Les chercheurs ajustent le modèle et la quantité de données pour trouver un équilibre entre ces deux défauts. On <b>valide</b> un modèle en vérifiant ses performances sur un ensemble de données <b>séparé</b> de l’entraînement, pour s’assurer qu’il généralise correctement avant de le déployer.</p>`)],
  [{q:'Un modèle entraîné à reconnaître des panneaux routiers réussit à 100 % sur les photos d’entraînement, mais se trompe souvent sur de nouvelles photos. Que s’est-il probablement passé ?',s:['Le modèle est probablement en surajustement : il a « appris par cœur » ses exemples.','Il généralise mal à des situations nouvelles qu’il n’a jamais vues.','Il faudrait l’entraîner avec plus de données variées, ou ajuster sa complexité.']}],
  ['Je distingue sous-ajustement et surajustement.','Je comprends pourquoi un modèle « parfait » sur ses exemples peut mal généraliser.','Je comprends l’intérêt de valider un modèle sur des données séparées.','Je peux expliquer un cas concret de surajustement.'],
  ['Croire qu’un modèle parfait sur ses exemples d’entraînement sera forcément parfait en pratique.','Confondre sous-ajustement (trop simple) et surajustement (trop collé aux exemples).','Négliger l’étape de validation sur des données séparées.'],
  ['Sous-ajustement : modèle trop simple.','Surajustement : modèle trop collé aux exemples, généralise mal.','Validation sur données séparées de l’entraînement.']),
 g:mix([d=>{const a=R(95,100),b=R(50,75);return ch(`Un modèle réussit ${a} % sur ses données d’entraînement mais seulement ${b} % sur des données nouvelles, jamais vues. Ce grand écart est le signe probable d’un…`,'surajustement (overfitting)',['sous-ajustement (underfitting)','fonctionnement parfaitement normal, sans aucun problème','manque total de données d’entraînement'],{expl:`Un très bon score à l’entraînement (${a} %) et un score bien plus faible sur des données nouvelles (${b} %) signale que le modèle a trop « collé » à ses exemples sans bien généraliser.`,hint:'Compare le score à l’entraînement et sur des données nouvelles.'});},2],
  [bank([
   ['Un modèle en sous-ajustement (underfitting) est…','trop simple pour bien capturer les régularités des données',['trop collé à ses exemples d’entraînement','parfaitement équilibré','impossible à obtenir en pratique'],'Il se trompe même sur ses propres exemples d’entraînement.'],
   ['Un modèle en surajustement (overfitting) réussit…','très bien sur ses exemples d’entraînement, mais mal sur des cas nouveaux',['mal sur ses exemples d’entraînement et bien sur des cas nouveaux','mal dans tous les cas, sans exception','parfaitement, dans tous les cas, sans aucune limite'],'Il a trop « appris par cœur » ses exemples.'],
   ['Pourquoi valider un modèle sur des données séparées de l’entraînement ?','pour vérifier qu’il généralise bien, pas seulement qu’il réussit ses propres exemples',['ce n’est jamais nécessaire','pour l’entraîner une seconde fois de la même façon','pour remplacer totalement l’entraînement'],'La validation révèle la vraie capacité de généralisation.'],
   ['Un grand écart entre la performance sur les données d’entraînement et sur des données nouvelles signale souvent…','un problème de surajustement',['un fonctionnement toujours normal','un manque de mémoire de l’ordinateur','une erreur d’affichage sans conséquence'],'C’est un indice classique de ce défaut.'],
   {tf:'Un modèle parfait sur ses exemples d’entraînement est nécessairement parfait aussi sur des cas nouveaux.',v:false,e:'C’est justement le risque du surajustement.'},
   {tf:'Trouver un bon équilibre entre sous-ajustement et surajustement fait partie du travail de conception d’un modèle.',v:true,e:'Les chercheurs ajustent modèle et données pour cet équilibre.',d:2},
  ['Augmenter la quantité et la variété des données d’entraînement peut-il aider à réduire le surajustement ?','oui, généralement',['non, cela aggrave toujours le surajustement','non, cela n’a aucun effet','non, cela ne concerne que le sous-ajustement'],'Plus d’exemples variés aident le modèle à mieux généraliser.'],
  ['Un modèle trop simple pour une tâche complexe illustre plutôt…','un sous-ajustement',['un surajustement','un fonctionnement optimal','un manque total de données, uniquement'],'Il ne capture pas assez les régularités nécessaires.'],
  ['« Apprendre par cœur » un cahier d’exercices sans comprendre la méthode est une image qui illustre…','le surajustement d’un modèle',['le sous-ajustement d’un modèle','le fonctionnement idéal d’un modèle','l’absence totale d’apprentissage'],'Réussir les exemples connus sans savoir généraliser.']]),2])},

{id:'ia3b',name:'Fiabilité, hallucinations et vérification',icon:'🧪',domain:'Esprit critique',
 refs:[TECH,CRCN,EDU],
 tip:'Pour un sujet complexe, appliquer la méthode de vérification vue en EMI (identifier l’affirmation, remonter à la source primaire, recouper, vérifier le contexte, conclure avec nuance) reste la meilleure protection contre les hallucinations d’IA.',
 c:C(`En 3e, on relie les connaissances sur les hallucinations d’IA (vues en 5e, ia5c) à la <b>méthode de vérification</b> approfondie en EMI (emi3a), pour construire une démarche rigoureuse face à des réponses d’IA sur des sujets <b>complexes</b> ou <b>controversés</b>.`,
  [T('Pourquoi la fiabilité varie selon le sujet',`<p>Une IA générative est généralement plus fiable sur des sujets <b>bien documentés</b> et <b>consensuels</b> (une formule mathématique connue, une date largement attestée) que sur des sujets <b>récents</b>, <b>spécialisés</b>, <b>controversés</b>, ou nécessitant un jugement nuancé. Le risque d’hallucination augmente quand l’information demandée est rare dans ses données d’entraînement.</p>`),
   T('Appliquer une méthode rigoureuse',`<p>Face à une réponse d’IA sur un sujet important : <b>identifier</b> précisément l’affirmation, chercher la <b>source primaire</b> si elle est citée, <b>recouper</b> avec au moins une source indépendante et reconnue, et formuler une <b>conclusion nuancée</b> plutôt que d’accepter ou de rejeter en bloc.</p>`)],
  [{q:'Une IA cite un chiffre très précis sur un sujet économique récent et spécialisé. Comment procéder ?',s:['Ce type de sujet (récent, spécialisé) augmente le risque d’hallucination.','Chercher la source primaire du chiffre si elle est mentionnée.','Recouper avec une source reconnue avant de réutiliser ce chiffre.']}],
  ['Je sais que la fiabilité d’une IA varie selon le type de sujet.','Je repère les sujets à risque élevé d’hallucination (récents, spécialisés, controversés).','J’applique la méthode de vérification en 5 étapes (EMI) aux réponses d’IA.','Je formule une conclusion nuancée plutôt que tout accepter ou tout rejeter.'],
  ['Croire qu’une IA est également fiable sur tous les types de sujets.','Ne pas appliquer de méthode de vérification systématique.','Accepter ou rejeter en bloc une réponse sans nuance.'],
  ['Fiabilité variable selon le sujet (consensuel vs controversé/récent).','Méthode EMI appliquée aux réponses d’IA.','Conclusion nuancée, pas tout ou rien.']),
 g:mix([sort({'Sujet où une IA est généralement plus fiable':['une formule mathématique très connue','une date historique largement documentée et non controversée'],'Sujet où le risque d’hallucination est plus élevé':['un événement très récent, encore mal documenté','un sujet scientifique de pointe, encore débattu entre spécialistes','une statistique précise rarement citée dans les sources habituelles']},{q:'« %s » :'}),2],
  [bank([
   ['Une IA est-elle également fiable sur tous les types de sujets ?','non, sa fiabilité varie selon que le sujet est bien documenté ou non',['oui, toujours exactement la même fiabilité','oui, car elle traite tous les sujets de la même façon','oui, seule la longueur de la réponse varie'],'Un sujet rare dans ses données augmente le risque d’erreur.'],
   ['Pourquoi un sujet très récent augmente-t-il le risque d’hallucination ?','il est probablement peu ou pas représenté dans les données d’entraînement',['il est toujours mieux documenté que les sujets anciens','cela n’a aucun lien avec les données d’entraînement','un sujet récent est toujours plus simple à traiter'],'Moins d’exemples disponibles signifie plus de risque d’erreur.'],
   ['La première étape de la méthode de vérification (vue en EMI) appliquée à une réponse d’IA est…','identifier précisément l’affirmation à vérifier',['publier immédiatement la réponse','ignorer la réponse sans l’examiner','répéter la question à l’identique en boucle'],'On précise ce qu’on veut vérifier avant de chercher à le confirmer.'],
   ['Une conclusion nuancée (« en partie vrai », « à confirmer ») est-elle préférable à un simple « vrai » ou « faux » pour un sujet complexe ?','oui, en général',['non, il faut toujours trancher de façon binaire','non, la nuance est toujours inutile','non, cela complique sans aucun bénéfice'],'La nuance reflète mieux la réalité d’un sujet incertain.'],
   {tf:'Le risque d’hallucination d’une IA est généralement plus élevé sur un sujet rare ou controversé que sur un sujet bien établi et documenté.',v:true,e:'Moins d’exemples fiables disponibles augmente le risque d’erreur.'},
   {tf:'La méthode de vérification vue en EMI ne s’applique qu’aux informations trouvées sur Internet, jamais à celles données par une IA.',v:false,e:'Elle s’applique de la même façon à toute information, y compris celle d’une IA.',d:2},
  ['Pour un sujet consensuel et largement documenté (par exemple une formule de physique bien établie), le risque d’hallucination d’une IA est généralement…','plus faible que pour un sujet rare ou récent',['toujours identique, quel que soit le sujet','toujours plus élevé que pour un sujet rare','impossible à estimer dans tous les cas'],'La richesse des exemples disponibles réduit le risque d’erreur.'],
  ['Recouper une affirmation donnée par une IA avec une encyclopédie reconnue relève…','de l’étape de recoupement avec une source indépendante',['d’une perte de temps inutile','d’une étape interdite par la méthode','d’une hallucination en elle-même'],'C’est l’une des étapes centrales de la méthode de vérification.']]),2])},

{id:'ia3c',name:'IA et orientation des décisions',icon:'⚙️',domain:'Société',
 refs:[TECH,CRCN,RGPD,EDU],
 tip:'Quand une IA influence une décision importante pour une personne (crédit, admission, recrutement), des règles existent, en Europe, pour exiger de la transparence et permettre un recours humain.',
 c:C(`Des IA interviennent de plus en plus dans des décisions qui concernent directement des personnes : accorder un <b>prêt bancaire</b>, présélectionner des <b>candidatures</b>, orienter des décisions de <b>justice</b> ou d’<b>admission</b> scolaire. Comprendre les enjeux de ces usages est une question de société.`,
  [T('Des décisions qui concernent des personnes',`<p>Une IA peut aider à <b>trier</b> ou <b>prioriser</b> des dossiers plus rapidement qu’un humain, mais cela pose des questions : sur quels <b>critères</b> ? Avec quelle <b>transparence</b> pour la personne concernée ? Avec quel risque de <b>biais</b> (voir ia4f) reproduisant des inégalités passées ?</p>`),
   T('Encadrement et droits',`<p>En Europe, le <b>RGPD</b> prévoit un droit à ne pas être soumis à une décision <b>entièrement automatisée</b> ayant des effets juridiques importants, sans intervention humaine possible, pour certains cas. Un règlement européen sur l’intelligence artificielle (<b>IA Act</b>), entré en vigueur en 2024 et appliqué par étapes sur plusieurs années, encadre aussi les usages à <b>haut risque</b> selon des règles renforcées (transparence, supervision humaine).</p>`)],
  [{q:'Une banque utilise une IA pour présélectionner les demandes de prêt. Quels enjeux cela pose-t-il ?',s:['Sur quels critères l’IA se base-t-elle, et sont-ils justes ?','Le demandeur a-t-il un droit à un recours humain si la décision le concerne fortement ?','Un biais dans les données passées pourrait-il désavantager certains profils ?']}],
  ['Je peux citer des exemples de décisions influencées par une IA.','Je comprends les enjeux de transparence et de critères.','Je sais qu’un droit à un recours humain existe dans certains cas en Europe (RGPD).','Je fais le lien avec le risque de biais déjà étudié (ia4f).'],
  ['Croire qu’une IA est toujours neutre et juste dans ses décisions.','Ignorer qu’un recours humain peut exister pour certaines décisions automatisées.','Oublier le risque que les biais des données passées influencent une décision future.'],
  ['IA dans des décisions importantes : crédit, recrutement, justice.','RGPD : droit à ne pas subir une décision entièrement automatisée dans certains cas.','Règlement européen sur l’IA : usages à haut risque encadrés.']),
 g:mix([bank([
  ['Le RGPD prévoit, dans certains cas, un droit à…','ne pas être soumis à une décision entièrement automatisée ayant des effets juridiques importants, sans recours humain possible',['être systématiquement jugé uniquement par une IA','ne jamais connaître les critères utilisés','refuser toute utilisation de données personnelles'],'Un recours humain peut être demandé dans ces cas.'],
  ['Pourquoi s’inquiéter d’un biais dans une IA utilisée pour présélectionner des candidatures ?','elle pourrait reproduire des inégalités présentes dans les données passées',['cela n’a jamais aucune conséquence','une IA ne peut jamais influencer une décision humaine','les candidatures ne contiennent jamais de données personnelles'],'Les données d’entraînement peuvent refléter des pratiques passées inégales.'],
  ['Un règlement européen sur l’intelligence artificielle (IA Act) encadre notamment…','les usages d’IA considérés comme « à haut risque »',['uniquement les jeux vidéo','uniquement les usages agricoles','aucun usage particulier'],'Il impose des règles renforcées de transparence et de supervision pour ces usages.',2],
  ['Une IA qui aide à trier des dossiers plus rapidement remplace-t-elle nécessairement toute intervention humaine ?','pas nécessairement : une supervision humaine peut rester prévue',['oui, toujours et systématiquement','oui, car la rapidité élimine toujours le besoin humain','oui, dans tous les cas sans exception'],'Le degré d’automatisation varie selon les systèmes et les règles applicables.'],
  {tf:'Une décision influencée par une IA peut avoir des conséquences réelles et importantes pour une personne (prêt, emploi, admission).',v:true,e:'C’est pourquoi un encadrement existe.'},
  {tf:'L’Union européenne n’a adopté aucune règle spécifique concernant l’intelligence artificielle.',v:false,e:'Un règlement européen sur l’IA encadre notamment les usages à haut risque.',d:2},
  ['Un système d’IA utilisé dans le domaine de la justice ou du recrutement entre-t-il, en général, dans la catégorie des usages « à haut risque » visés par ces règles ?','oui, en général, du fait de l’importance des conséquences pour les personnes',['non, jamais','non, ces domaines ne sont jamais concernés','non, uniquement les usages dans les jeux vidéo sont concernés'],'L’impact important sur les personnes justifie un encadrement renforcé.',2],
  ['Un employeur qui utilise une IA pour présélectionner des candidatures doit-il, selon les règles en vigueur en Europe, pouvoir expliquer les critères utilisés en cas de recours ?','oui, en principe, une forme de transparence est attendue pour ce type d’usage',['non, aucune explication n’est jamais exigée','non, les critères doivent toujours rester totalement secrets','non, cela ne concerne que les très petites entreprises'],'La transparence fait partie des exigences prévues pour ces usages.',3],
  ['Le terme « haut risque », dans ce contexte, désigne des usages d’IA…','dont les conséquences possibles sur les personnes sont jugées particulièrement importantes',['sans aucune conséquence notable','réservés uniquement aux jeux vidéo','concernant uniquement les objets connectés domestiques'],'Justice, santé, recrutement, crédit en font partie.',2],
  ['Une décision de justice peut-elle, selon les règles en vigueur en Europe, être prise entièrement par une IA sans aucune intervention humaine ?','non, un contrôle humain reste prévu pour ce type de décision',['oui, systématiquement et sans aucun contrôle','oui, car cela accélère toujours la justice sans poser de problème','oui, dans tous les pays du monde sans exception'],'Les décisions à fort impact humain restent encadrées par un contrôle humain.',3],
  ['Pourquoi est-il important que la personne concernée par une décision influencée par une IA puisse comprendre les critères utilisés ?','pour pouvoir contester la décision si elle l’estime injuste',['ce n’est jamais important','pour rendre la décision plus rapide uniquement','pour remplacer totalement le recours humain'],'La transparence permet un recours effectif.'],
  ['Les organismes qui utilisent une IA pour des décisions importantes doivent-ils, selon ces règles, documenter leur système (fonctionnement, données, tests réalisés) ?','oui, une forme de documentation et de traçabilité est en principe exigée pour les usages à haut risque',['non, aucune documentation n’est jamais demandée','non, cela concerne uniquement les petites structures','non, cela ne concerne que les usages sans aucun risque'],'La documentation facilite le contrôle et la responsabilité.',3]]),2])},

{id:'ia3d',name:'IA, travail et métiers',icon:'🧑‍💼',domain:'Société',
 refs:[TECH,CRCN,EDU],
 tip:'L’IA transforme des métiers plus souvent qu’elle ne les supprime entièrement : certaines tâches répétitives peuvent être automatisées, tandis que de nouvelles compétences et de nouveaux métiers émergent.',
 c:C(`L’intelligence artificielle transforme de nombreux <b>métiers</b> : certaines tâches sont automatisées, d’autres <b>compétences</b> deviennent plus demandées, et de <b>nouveaux métiers</b> apparaissent. Comprendre ces transformations aide à anticiper, sans céder à des idées trop simples (ni la peur, ni la promesse de solutions magiques).`,
  [T('Automatisation et transformation',`<p>Certaines <b>tâches répétitives</b> ou prévisibles (tri de documents, réponses standard, calculs répétitifs) peuvent être partiellement <b>automatisées</b>. Mais un métier est rarement composé d’une seule tâche : il est plus fréquent qu’une partie des tâches soit transformée que le métier entier supprimé.</p>`),
   T('Compétences recherchées et nouveaux métiers',`<p>Des compétences comme le <b>jugement critique</b>, la <b>créativité</b>, les <b>relations humaines</b> (soin, écoute, négociation) restent difficiles à automatiser. De nouveaux métiers apparaissent autour de l’IA elle-même : <b>entraînement</b> de modèles, <b>vérification</b> de leurs résultats, <b>conception éthique</b>, <b>réglementation</b>.</p>`)],
  [{q:'Un métier administratif comprend des tâches de tri de documents et des tâches de conseil personnalisé aux usagers. Comment l’IA pourrait-elle le transformer ?',s:['Le tri de documents répétitif pourrait être partiellement automatisé.','Le conseil personnalisé, qui demande écoute et jugement, reste plus difficile à automatiser.','Le métier serait probablement transformé plutôt que totalement supprimé.']}],
  ['Je comprends que l’automatisation touche souvent des tâches, pas des métiers entiers.','Je peux citer des compétences humaines difficiles à automatiser.','Je peux citer des exemples de nouveaux métiers liés à l’IA.','J’évite les idées trop simples (ni peur excessive, ni solution magique).'],
  ['Croire que tous les métiers vont disparaître à cause de l’IA.','Croire que l’IA ne changera jamais aucun métier.','Négliger l’émergence de nouveaux métiers liés à l’IA.'],
  ['Automatisation de tâches ≠ suppression totale d’un métier.','Compétences difficiles à automatiser : jugement, créativité, relations humaines.','Nouveaux métiers : entraînement, vérification, éthique, réglementation.']),
 g:mix([sort({'Tâche plus facilement automatisable':['trier de grandes quantités de documents selon des critères simples','effectuer des calculs répétitifs standardisés'],'Compétence difficile à automatiser':['écouter et conseiller une personne dans une situation complexe et unique','faire preuve de créativité pour résoudre un problème inédit','négocier un accord entre plusieurs parties aux intérêts différents']},{q:'« %s » relève plutôt d’une…'}),2],
  [bank([
   ['L’automatisation par IA touche le plus souvent…','certaines tâches d’un métier, plutôt que le métier entier',['toujours la totalité d’un métier, sans exception','aucune tâche, jamais','uniquement les métiers manuels'],'Un métier regroupe en général plusieurs tâches différentes.'],
   ['Quelle compétence reste généralement difficile à automatiser ?','le jugement critique dans une situation complexe et nouvelle',['le tri répétitif de documents standards','un calcul simple répété à l’identique','la copie exacte d’un texte'],'Les situations inédites demandent une adaptation difficile à automatiser.'],
   ['Un métier lié à la vérification des résultats produits par une IA est…','un exemple de nouveau métier apparu avec le développement de l’IA',['un métier qui n’existe pas','un métier totalement automatisé lui-même','un métier sans aucun lien avec l’IA'],'De nouveaux métiers accompagnent le développement de cette technologie.'],
   ['Penser que « l’IA va forcément supprimer tous les métiers » est-il une analyse nuancée ?','non, c’est une généralisation excessive',['oui, c’est toujours exactement ce qui se passe','oui, c’est une certitude scientifique','oui, cela concerne absolument tous les métiers'],'La réalité est plus complexe, avec des transformations variées selon les métiers.',2],
   {tf:'Un métier peut être transformé par l’IA sans disparaître entièrement.',v:true,e:'C’est souvent une partie des tâches qui évolue, pas le métier dans son ensemble.'},
   {tf:'Aucun nouveau métier n’a jamais émergé en lien avec le développement de l’intelligence artificielle.',v:false,e:'Des métiers liés à l’entraînement, la vérification ou l’éthique de l’IA sont apparus.',d:2},
  ['Les compétences liées aux relations humaines (écoute, empathie, soin aux autres) restent-elles recherchées dans un monde du travail transformé par l’IA ?','oui, ces compétences restent difficiles à automatiser',['non, elles deviennent totalement inutiles','non, une IA les remplace parfaitement dans tous les cas','non, elles n’ont jamais été recherchées'],'Les métiers du soin et de la relation humaine restent peu automatisables.']]),2])},

{id:'ia3e',name:'Vie privée, sécurité et usages de l’IA',icon:'🛡️',domain:'Protection',
 refs:[TECH,CRCN,RGPD,EDU],
 tip:'L’IA peut servir à la fois à mieux protéger (détection de fraudes, filtrage de contenus malveillants) et, utilisée à des fins malveillantes, à créer de nouvelles menaces (hypertrucages, messages d’hameçonnage très convaincants) : comprendre les deux faces aide à se protéger.',
 c:C(`En 3e, on relie les connaissances sur la protection des données (ia5e) aux enjeux plus larges de <b>sécurité</b> liés à l’IA : comment cette technologie peut-elle à la fois <b>renforcer</b> et <b>menacer</b> la sécurité numérique ?`,
  [T('L’IA au service de la sécurité',`<p>Des IA aident à <b>détecter</b> des fraudes bancaires inhabituelles, à <b>filtrer</b> des courriels d’hameçonnage ou des contenus malveillants, ou à repérer des <b>comportements suspects</b> sur un réseau informatique.</p>`),
   T('L’IA comme nouvelle menace possible',`<p>À l’inverse, l’IA générative peut servir à créer des messages d’<b>hameçonnage</b> très convaincants et personnalisés (voir pix4f), ou des <b>hypertrucages</b> utilisés pour usurper une identité (voir emi3d). Se protéger demande donc une vigilance renforcée : vérifier la source d’un message même très bien rédigé, se méfier d’une voix ou d’une vidéo « trop » convaincante dans un contexte suspect.</p>`)],
  [{q:'Une banque utilise une IA pour détecter des transactions inhabituelles sur un compte. À l’inverse, un escroc utilise une IA pour générer un message d’hameçonnage très personnalisé. Que montre cette comparaison ?',s:['La même technologie peut servir à protéger ou à menacer, selon l’usage qui en est fait.','La vigilance reste nécessaire même face à un message très bien rédigé.','Comprendre ces deux usages aide à se protéger plus efficacement.']}],
  ['Je peux citer un usage de l’IA au service de la sécurité.','Je peux citer un usage malveillant possible de l’IA.','Je comprends que la qualité apparente d’un message n’en garantit pas la légitimité.','Je fais le lien avec l’hameçonnage et les hypertrucages déjà étudiés.'],
  ['Croire que l’IA ne sert qu’à protéger, jamais à menacer.','Baisser sa vigilance face à un message très bien rédigé, pensant qu’un escroc ne pourrait pas l’écrire aussi bien.','Ignorer le lien entre IA générative et hypertrucages.'],
  ['IA pour la sécurité : détection de fraude, filtrage.','IA comme menace : hameçonnage personnalisé, hypertrucages.','Vigilance renforcée, même face à un contenu très convaincant.']),
 g:mix([sort({'IA au service de la sécurité':['détecter une transaction bancaire inhabituelle','filtrer automatiquement les courriels d’hameçonnage','repérer un comportement suspect sur un réseau'],'IA utilisée à des fins malveillantes':['générer un message d’hameçonnage très personnalisé','créer une fausse vidéo pour usurper une identité (hypertrucage)','imiter une voix pour tromper un proche']},{q:'« %s » est un exemple de…'}),2],
  [bank([
   ['Comment une IA peut-elle aider à la sécurité numérique ?','en détectant des transactions ou comportements inhabituels',['elle ne peut jamais y contribuer','uniquement en ralentissant les ordinateurs','uniquement en supprimant tous les comptes suspects'],'La détection d’anomalies est un usage fréquent.'],
   ['Un message d’hameçonnage généré par IA peut-il être très bien écrit, sans fautes ?','oui, ce qui le rend plus difficile à repérer qu’avant',['non, il contient toujours des fautes évidentes','non, l’IA ne peut jamais écrire sans fautes','non, cela n’existe pas'],'La qualité de rédaction n’est plus un indice fiable à elle seule.'],
   ['Un hypertrucage (deepfake) peut-il être utilisé pour usurper l’identité d’une personne ?','oui, c’est un risque documenté',['non, jamais','non, c’est techniquement impossible','non, cela ne concerne que les célébrités'],'Voir aussi le chapitre d’EMI sur l’IA générative (emi3d).'],
   ['La même technologie (IA générative) peut-elle servir à protéger et à menacer selon l’usage ?','oui',['non, elle ne sert jamais à protéger','non, elle ne sert jamais à menacer','non, cela dépend uniquement de sa marque'],'C’est l’usage qui en est fait qui détermine l’effet, pas la technologie elle-même.'],
   {tf:'La qualité apparente (orthographe, mise en forme) d’un message suffit à garantir sa légitimité.',v:false,e:'Un message malveillant généré par IA peut être très bien rédigé.'},
   {tf:'Des IA sont utilisées par des banques et des services de sécurité pour détecter des fraudes.',v:true,e:'C’est un usage fréquent et légitime de cette technologie.',d:2}]),2])},

{id:'ia3f',name:'Construire une démarche responsable avec l’IA',icon:'🧩',domain:'Projet',
 refs:[TECH,CRCN,PIXIA,EDU],
 tip:'Une charte personnelle d’usage de l’IA peut tenir en quelques principes simples : vérifier, protéger ses données, respecter les règles, rester transparent, et ne jamais confier une décision importante à l’IA seule.',
 c:C(`En fin de collège, ce chapitre propose de <b>synthétiser</b> l’ensemble des connaissances acquises sur l’IA (fonctionnement, limites, biais, droits, société) pour construire une véritable <b>démarche personnelle</b> et responsable, transférable au lycée et à la vie quotidienne.`,
  [T('Rassembler ce qu’on a appris',`<p>Fonctionnement (ia6a, ia4a, ia3a) ; limites et hallucinations (ia6c, ia5c, ia3b) ; biais et équité (ia5d, ia4f) ; protection des données (ia6d, ia5e, ia3e) ; droits et société (ia4g, ia3c, ia3d). Chacun de ces aspects éclaire une facette différente d’un usage responsable.</p>`),
   T('Formuler des principes personnels',`<p>Une démarche responsable peut se résumer en quelques principes : <b>vérifier</b> systématiquement les informations importantes ; <b>protéger</b> ses données et celles des autres ; <b>respecter</b> les règles fixées (école, loi) ; être <b>transparent</b> sur son usage quand c’est pertinent ; ne jamais laisser une IA seule décider d’une question importante sans contrôle humain.</p>`)],
  [{q:'Formule, en t’appuyant sur ce que tu as appris, trois principes personnels pour un usage responsable de l’IA.',s:['« Je vérifie toujours les informations importantes avec une source indépendante. »','« Je ne partage jamais de données personnelles sensibles avec une IA. »','« Je garde un contrôle humain sur les décisions qui me concernent vraiment. »']}],
  ['Je peux relier les différents chapitres étudiés sur l’IA entre eux.','Je peux formuler des principes personnels d’usage responsable.','Je comprends que ces principes s’appliquent à la vie quotidienne, pas seulement à l’école.','Je peux expliquer pourquoi chaque principe est important.'],
  ['Considérer ces connaissances comme isolées, sans lien entre elles.','Ne formuler aucun principe personnel concret.','Penser que ces règles ne s’appliquent qu’au cadre scolaire.'],
  ['Synthèse : fonctionnement, limites, biais, droits, société.','Principes : vérifier, protéger, respecter, être transparent, garder un contrôle humain.','Application à la vie quotidienne, pas seulement scolaire.']),
 g:mix([bank([
  ['Pourquoi relier les différents aspects de l’IA (fonctionnement, limites, biais, droits) est-il utile ?','parce qu’un usage responsable combine plusieurs vigilances complémentaires',['parce qu’un seul de ces aspects suffit toujours','parce que ces aspects n’ont aucun lien entre eux','parce que c’est une obligation administrative sans autre intérêt'],'Chaque aspect éclaire une dimension différente du même sujet.'],
  ['« Ne jamais laisser une IA seule décider d’une question importante » relève…','d’un principe de contrôle humain sur les décisions importantes',['d’une règle sans aucun fondement','d’une interdiction totale d’utiliser l’IA','d’une règle qui ne concerne que les adultes'],'Le contrôle humain reste essentiel sur les sujets sensibles.'],
  ['Les principes d’usage responsable de l’IA appris au collège s’appliquent-ils uniquement à l’école ?','non, ils restent utiles dans la vie quotidienne et au lycée',['oui, uniquement à l’école','oui, uniquement jusqu’au brevet','oui, uniquement pendant les cours d’informatique'],'Ces réflexes sont transférables à de nombreuses situations.'],
  ['Être « transparent » sur son usage de l’IA signifie notamment…','ne pas cacher qu’on a utilisé une IA quand cela compte pour comprendre le travail réalisé',['utiliser l’IA sans aucune limite','ne jamais utiliser l’IA','cacher systématiquement son usage'],'La transparence reste une marque d’honnêteté intellectuelle.'],
  {tf:'Une démarche responsable d’usage de l’IA combine plusieurs principes complémentaires (vérification, protection des données, respect des règles, transparence, contrôle humain).',v:true,e:'Aucun principe seul ne suffit à garantir un usage responsable complet.'},
  {tf:'Les connaissances acquises sur l’IA au collège ne serviront plus une fois le collège terminé.',v:false,e:'Ces compétences restent utiles au lycée et dans la vie quotidienne.',d:2},
  ['Protéger ses données personnelles quand on utilise une IA (ia5e, ia3e) relève de quel grand principe d’une démarche responsable ?','protéger ses données et celles des autres',['vérifier les informations uniquement','respecter les règles fixées uniquement','rester transparent uniquement'],'Chaque chapitre étudié éclaire un principe différent de la démarche globale.'],
  ['Comprendre les biais possibles d’une IA (ia5d, ia4f) aide surtout à appliquer quel principe ?','garder un regard critique et vérifier l’équité des résultats produits',['uniquement protéger ses données personnelles','uniquement respecter les règles de l’établissement','uniquement être transparent sur son usage'],'La connaissance des biais nourrit la vigilance critique.'],
  ['Pourquoi aucun principe seul (vérifier, protéger, respecter, être transparent, garder un contrôle humain) ne suffit-il à garantir, à lui seul, un usage totalement responsable ?','parce que ces principes se complètent et couvrent des risques différents',['parce qu’un seul de ces principes couvre en réalité tous les risques possibles','parce qu’aucun de ces principes n’est réellement utile','parce que ces principes se contredisent entre eux'],'Chaque principe répond à un type de risque différent.'],
  ['Appliquer ces principes dans une situation nouvelle, non rencontrée explicitement au collège, relève…','d’un transfert des compétences apprises à une situation inédite',['d’une impossibilité totale','d’une règle réservée uniquement aux exercices scolaires','d’un hasard sans aucun lien avec l’apprentissage'],'C’est l’objectif même d’apprendre des principes généraux plutôt que des cas isolés.'],
  ['Discuter de ces principes avec d’autres personnes (famille, camarades) peut-il aider à mieux les faire vivre au quotidien ?','oui, l’échange permet de confronter et d’affiner ces principes',['non, cela n’a jamais aucun intérêt','non, ces principes doivent rester secrets','non, un seul avis individuel suffit toujours'],'Le dialogue enrichit la réflexion sur un usage responsable.'],
  ['Réévaluer régulièrement ses propres habitudes d’usage de l’IA, à mesure que la technologie évolue, est-il pertinent ?','oui, car les outils et leurs usages évoluent rapidement',['non, les habitudes apprises une fois suffisent pour toujours','non, cela n’a aucun sens','non, la technologie reste toujours identique dans le temps'],'Une démarche responsable s’adapte à un domaine qui évolue vite.']]),2])}
]);

})();
